n42558.content:
\begin{definition}[Sub-distribution]
  \label{def:sdistr}
  \lean{CatCrypt.Prob.SDistr}
  \leanok
  A \emph{sub-distribution} over a type $\alpha$ is a probability mass function
  on $\mathrm{Option}\,\alpha$; the mass on $\mathsf{none}$ absorbs the missing
  weight, so a sub-distribution may sum to less than one. This makes partial and
  failing computations first-class.
\end{definition}

n42559.content:
\begin{definition}[Typed heap]
  \label{def:heap}
  \lean{CatCrypt.Core.Heap}
  \leanok
  A \emph{heap} is a typed store: a finite map from typed locations to their
  values, the mutable state a computation reads and writes.
\end{definition}

n42560.content:
\begin{definition}[Stateful-probabilistic computation]
  \label{def:spcomp}
  \uses{def:sdistr, def:heap}
  \lean{CatCrypt.Core.SPComp}
  \leanok
  A \emph{stateful-probabilistic computation} returning $\alpha$ maps an initial
  heap to a sub-distribution over its result paired with the final heap:
  \[
    \mathsf{SPComp}\,\alpha \;=\; \mathrm{Heap} \to \mathrm{SDistr}(\alpha \times \mathrm{Heap}).
  \]
\end{definition}

n42561.content:
\begin{definition}[Monad operations]
  \label{def:spcomp-ops}
  \uses{def:spcomp}
  \lean{CatCrypt.Core.SPComp.pure, CatCrypt.Core.SPComp.bind, CatCrypt.Core.SPComp.sample}
  \leanok
  $\mathsf{SPComp}$ carries $\mathsf{pure}$ (the Dirac computation), $\mathsf{bind}$
  (sequential composition threading the heap), and $\mathsf{sample}$ (drawing from
  a distribution).
\end{definition}

n42565.content:
\begin{definition}[Constructors and bind]
  \label{def:sdistr-ops}
  \uses{def:sdistr}
  \lean{CatCrypt.Prob.SDistr.pure, CatCrypt.Prob.SDistr.bind, CatCrypt.Prob.SDistr.fail}
  \leanok
  $\mathsf{SDistr}$ carries the point mass $\mathsf{pure}\,a$ (all weight on
  $\mathsf{some}\,a$), the failing computation $\mathsf{fail}$ (all weight on
  $\mathsf{none}$), and the monadic bind $\mathsf{bind}\,d\,f$, which samples
  $d$ and, on a successful outcome $a$, continues with $f\,a$, while a failure
  of $d$ propagates to failure of the whole computation. These make
  $\mathsf{SDistr}$ a monad.
\end{definition}

n42566.content:
\begin{definition}[Uniform distribution]
  \label{def:sdistr-uniform}
  \uses{def:sdistr}
  \lean{CatCrypt.Prob.SDistr.uniform}
  \leanok
  For a finite nonempty type $\alpha$, the uniform sub-distribution
  $\mathsf{uniform}\,\alpha$ places mass $1/\lvert\alpha\rvert$ on every
  $\mathsf{some}\,a$ and mass $0$ on $\mathsf{none}$.
\end{definition}

n42567.content:
\begin{definition}[Mass and support]
  \label{def:sdistr-measures}
  \uses{def:sdistr}
  \lean{CatCrypt.Prob.SDistr.mass, CatCrypt.Prob.SDistr.support}
  \leanok
  The \emph{mass} of $d$ is $\mathsf{mass}\,d = 1 - d(\mathsf{none})$, the total
  probability of not failing. The \emph{support} of $d$ is the set
  $\{\,a \mid d(\mathsf{some}\,a) \neq 0\,\}$ of outcomes with nonzero
  probability.
\end{definition}

n42568.content:
\begin{lemma}[Monad laws]
  \label{lem:sdistr-monad-laws}
  \uses{def:sdistr-ops}
  \lean{CatCrypt.Prob.SDistr.pure_bind, CatCrypt.Prob.SDistr.bind_pure, CatCrypt.Prob.SDistr.bind_assoc}
  \leanok
  Bind satisfies the three monad laws: left identity
  $\mathsf{bind}\,(\mathsf{pure}\,a)\,f = f\,a$, right identity
  $\mathsf{bind}\,d\,\mathsf{pure} = d$, and associativity
  $\mathsf{bind}\,(\mathsf{bind}\,d\,f)\,g
   = \mathsf{bind}\,d\,(\lambda a.\,\mathsf{bind}\,(f\,a)\,g)$.
\end{lemma}

n42569.content:
\begin{lemma}[Congruence on the support]
  \label{lem:bind-congr-support}
  \uses{def:sdistr-ops, def:sdistr-measures}
  \lean{CatCrypt.Prob.SDistr.bind_congr_support}
  \leanok
  If two continuations $f$ and $g$ agree on every outcome in the support of
  $d$, that is $f\,a = g\,a$ whenever $d(\mathsf{some}\,a) \neq 0$, then
  $\mathsf{bind}\,d\,f = \mathsf{bind}\,d\,g$. Behaviour off the support is
  irrelevant because it carries no weight.
\end{lemma}

n42570.content:
\begin{lemma}[Bijection on a uniform distribution]
  \label{lem:uniform-bind-bij}
  \uses{def:sdistr-ops, def:sdistr-uniform}
  \lean{CatCrypt.Prob.SDistr.uniform_bind_bij}
  \leanok
  Pushing a bijection $f : \alpha \simeq \beta$ through a uniform distribution
  yields the uniform distribution on the target:
  $\mathsf{bind}\,(\mathsf{uniform}\,\alpha)\,(\lambda a.\,\mathsf{pure}\,(f\,a))
   = \mathsf{uniform}\,\beta$. This is the reindexing invariance underlying
  one-time-pad arguments.
\end{lemma}

n42571.content:
\begin{lemma}[Bind support witness]
  \label{lem:bind-support-witness}
  \uses{def:sdistr-ops, def:sdistr-measures}
  \lean{CatCrypt.Prob.SDistr.bind_support_witness}
  \leanok
  If a bind has nonzero probability on some final outcome $b$, that is
  $(\mathsf{bind}\,d\,f)(\mathsf{some}\,b) \neq 0$, then there is an
  intermediate outcome $a$ with $d(\mathsf{some}\,a) \neq 0$ and
  $(f\,a)(\mathsf{some}\,b) \neq 0$. This extracts an existential witness from a
  probability observation, and drives the unary probabilistic Hoare logic.
\end{lemma}

n42572.content:
\begin{definition}[Coupling]
  \label{def:coupling}
  \uses{def:sdistr, def:sdistr-ops}
  \lean{CatCrypt.Prob.Coupling}
  \leanok
  A \emph{coupling} of $d_1 : \mathsf{SDistr}\,\alpha$ and
  $d_2 : \mathsf{SDistr}\,\beta$ is a joint sub-distribution
  $\mathsf{joint} : \mathsf{SDistr}(\alpha \times \beta)$ whose two projections
  reproduce the given marginals: the left marginal of $\mathsf{joint}$ equals
  $d_1$ and the right marginal equals $d_2$.
\end{definition}

n42573.content:
\begin{definition}[Satisfying a relation]
  \label{def:coupling-satisfies}
  \uses{def:coupling}
  \lean{CatCrypt.Prob.Coupling.satisfies}
  \leanok
  A coupling $c$ \emph{satisfies} a relation $R : \alpha \to \beta \to
  \mathrm{Prop}$ when every jointly-supported pair is related: for all $a, b$,
  if $c.\mathsf{joint}(\mathsf{some}\,(a,b)) \neq 0$ then $R\,a\,b$.
\end{definition}

n42574.content:
\begin{definition}[Lifting a relation]
  \label{def:liftr}
  \uses{def:coupling, def:coupling-satisfies}
  \lean{CatCrypt.Prob.liftR}
  \leanok
  A relation $R$ \emph{lifts} to sub-distributions $d_1$ and $d_2$, written
  $d_1\,\langle R\rangle\#\,d_2$, when there exists a coupling of $d_1$ and
  $d_2$ that satisfies $R$. This is the probabilistic analogue of a relational
  postcondition.
\end{definition}

n42575.content:
\begin{definition}[Diagonal and bijection couplings]
  \label{def:coupling-constructions}
  \uses{def:coupling, def:sdistr-ops}
  \lean{CatCrypt.Prob.Coupling.diagonal, CatCrypt.Prob.Coupling.fromBij}
  \leanok
  The \emph{diagonal} coupling of $d$ with itself pairs each outcome with
  itself, via $\mathsf{bind}\,d\,(\lambda a.\,\mathsf{pure}\,(a,a))$. The
  \emph{bijection} coupling of $d$ with its image under $f : \alpha \simeq
  \beta$ pairs each $a$ with $f\,a$, via
  $\mathsf{bind}\,d\,(\lambda a.\,\mathsf{pure}\,(a, f\,a))$.
\end{definition}

n42576.content:
\begin{lemma}[Reflexivity of lifting]
  \label{lem:liftr-refl}
  \uses{def:liftr, def:coupling-constructions}
  \lean{CatCrypt.Prob.liftR_refl}
  \leanok
  Equality lifts to any sub-distribution: $d\,\langle {=}\rangle\#\,d$, witnessed
  by the diagonal coupling.
\end{lemma}

n42577.content:
\begin{lemma}[Lifting of pure]
  \label{lem:liftr-pure}
  \uses{def:liftr, def:sdistr-ops}
  \lean{CatCrypt.Prob.liftR_pure}
  \leanok
  If $R\,a\,b$ holds then it lifts to the point masses:
  $(\mathsf{pure}\,a)\,\langle R\rangle\#\,(\mathsf{pure}\,b)$.
\end{lemma}

n42578.content:
\begin{theorem}[Lifting composes through bind]
  \label{thm:liftr-bind}
  \uses{def:liftr, lem:bind-congr-support, lem:liftr-pure}
  \lean{CatCrypt.Prob.liftR_bind}
  \leanok
  If $R$ lifts to $d_1, d_2$ and, for every related pair $a, b$ with $R\,a\,b$,
  the postcondition $S$ lifts to the continuations $f_1\,a, f_2\,b$, then $S$
  lifts to the bound computations:
  $(\mathsf{bind}\,d_1\,f_1)\,\langle S\rangle\#\,(\mathsf{bind}\,d_2\,f_2)$.
  This is the sequencing rule of probabilistic relational Hoare logic.
\end{theorem}

n42579.content:
\begin{lemma}[Uniform distributions lift along a bijection]
  \label{lem:liftr-uniform-bij}
  \uses{def:liftr, lem:uniform-bind-bij}
  \lean{CatCrypt.Prob.liftR_uniform_bij}
  \leanok
  For a bijection $f : \alpha \simeq \beta$, the relation
  $\lambda a\,b.\,f\,a = b$ lifts to the two uniform distributions:
  $(\mathsf{uniform}\,\alpha)\,\langle \lambda a\,b.\,f\,a = b\rangle\#\,
   (\mathsf{uniform}\,\beta)$.
\end{lemma}

n42580.content:
\begin{theorem}[Gauss sum in extended reals]
  \label{thm:gauss-sum}
  \lean{CatCrypt.Prob.BirthdayBound.gauss_sum_ennreal}
  \leanok
  For any $q \in \mathbb{N}$ and $N \in \overline{\mathbb{R}}_{\geq 0}$,
  \[
    \sum_{i < q} \frac{i}{N} = \frac{q(q-1)/2}{N}.
  \]
\end{theorem}

n42581.content:
\begin{theorem}[Birthday bound from per-step bounds]
  \label{thm:birthday-bound-sum}
  \uses{thm:gauss-sum}
  \lean{CatCrypt.Prob.BirthdayBound.birthday_bound_sum}
  \leanok
  If the collision probability at step $i$ is at most $i/N$ for every $i < q$,
  then the total collision probability, bounded by the union bound, is at most
  $q(q-1)/(2N)$:
  \[
    \sum_{i < q} \mathsf{step\_pr}(i) \leq \frac{q(q-1)/2}{N}.
  \]
\end{theorem}

n42582.content:
\begin{theorem}[Birthday bound for advantage]
  \label{thm:birthday-advantage}
  \uses{thm:birthday-bound-sum, def:spcomp}
  \lean{CatCrypt.Prob.BirthdayBound.birthday_advantage}
  \leanok
  Given a family of games $G_0, \dots, G_q$ where the distinguishing advantage
  of the step $i \to i+1$ is at most $i/N$, the advantage between the endpoints
  $G_0$ and $G_q$ is at most $q(q-1)/(2N)$. This combines the birthday
  arithmetic with the hybrid argument.
\end{theorem}

n42583.content:
\begin{theorem}[Schwartz--Zippel]
  \label{thm:schwartz-zippel}
  \uses{def:spcomp-ops}
  \lean{CatCrypt.Prob.schwartz_zippel}
  \leanok
  For a nonzero polynomial $\varphi$ over $\mathbb{Z}/p\mathbb{Z}$ with $p$
  prime, a uniformly random point is a root with probability at most
  $\deg\varphi / p$:
  \[
    \operatorname{Pr}_{x \leftarrow \mathbb{Z}/p\mathbb{Z}}[\varphi(x) = 0]
    \;\leq\; \frac{\deg\varphi}{p}.
  \]
\end{theorem}

n42584.content:
\begin{corollary}[Polynomial identity testing]
  \label{cor:poly-identity}
  \uses{thm:schwartz-zippel}
  \lean{CatCrypt.Prob.poly_identity_test}
  \leanok
  For distinct polynomials $\varphi \neq \psi$ over $\mathbb{Z}/p\mathbb{Z}$, a
  uniformly random point satisfies $\varphi(x) = \psi(x)$ with probability at
  most $\max(\deg\varphi, \deg\psi)/p$, obtained by applying Schwartz--Zippel to
  the nonzero difference $\varphi - \psi$.
\end{corollary}

n42585.content:
\begin{definition}[XOR bijections]
  \label{def:xor-bij}
  \lean{CatCrypt.Prob.XorBij.xorEquiv, CatCrypt.Prob.XorBij.boolXorBij, CatCrypt.Prob.XorBij.boolXorBij_symm}
  \leanok
  For an involutive binary operation $\mathsf{op}$ satisfying
  $\mathsf{op}\,(\mathsf{op}\,a\,b)\,b = a$, the map $k \mapsto \mathsf{op}\,k\,x$
  is a self-inverse equivalence $\alpha \simeq \alpha$. Its specialisation to
  boolean exclusive-or, $k \mapsto k \oplus x$, is the bijection underlying
  one-time-pad, PRF, MAC, and PRG proofs.
\end{definition}

n42586.content:
\begin{lemma}[Sampling through a bijection is indistinguishable]
  \label{lem:rhoare-sample-bij}
  \uses{def:xor-bij, lem:liftr-uniform-bij, thm:liftr-bind, lem:liftr-pure}
  \lean{CatCrypt.Prob.XorBij.rHoare_sample_bij}
  \leanok
  For any bijection $f : \alpha \simeq \alpha$ on a finite nonempty type,
  sampling a uniform key and applying $f$ is relationally equivalent to sampling
  uniformly: the programs $k \leftarrow \mathsf{sample}\,\alpha;\;
  \mathsf{pure}\,(f\,k)$ and $\mathsf{sample}\,\alpha$ are coupled by equality on
  their outputs. Consequently every distinguisher has zero advantage against the
  XOR one-time pad.
\end{lemma}

n42587.content:
\begin{definition}[Set probability and conditioning]
  \label{def:pmf-condprob}
  \lean{PMF.prob, PMF.condProb}
  \leanok
  For a probability mass function $p$, the probability of a set $A$ is
  $\operatorname{Pr}_p[A] = \sum_a \mathbf{1}_A(a)\,p(a)$, and the conditional probability of
  $A$ given $B$ is $\operatorname{Pr}_p[A \mid B] = \operatorname{Pr}_p[A \cap B] / \operatorname{Pr}_p[B]$.
\end{definition}

n42588.content:
\begin{theorem}[Bayes' theorem]
  \label{thm:bayes}
  \uses{def:pmf-condprob}
  \lean{PMF.bayes_theorem}
  \leanok
  For any events $A, B$ under a mass function $p$,
  $\operatorname{Pr}_p[A \mid B]\cdot\operatorname{Pr}_p[B] = \operatorname{Pr}_p[B \mid A]\cdot\operatorname{Pr}_p[A]$.
\end{theorem}

n42589.content:
\begin{definition}[Bayesian inversion and recovery]
  \label{def:bayes-inv}
  \uses{def:pmf-condprob}
  \lean{CatCrypt.Prob.bayesInv, CatCrypt.Prob.bayesInv_recovery}
  \leanok
  Given a prior $\pi$ over $\alpha$ and a likelihood $f : \alpha \to
  \mathrm{PMF}\,\beta$, the posterior $\mathsf{bayesInv}\,\pi\,f\,b$ is the
  normalisation of $a \mapsto \pi(a)\cdot f(a)(b)$ (defined whenever the
  $\beta$-marginal at $b$ is nonzero). It satisfies the discrete recovery
  equation $\mathsf{posterior}(a)\cdot\mathsf{marginal}(b) = \pi(a)\cdot f(a)(b)$.
\end{definition}

n42590.content:
\begin{definition}[Game]
  \label{def:game}
  \uses{def:spcomp}
  \lean{CatCrypt.Crypto.Game}
  \leanok
  A \emph{game} is a Boolean-valued stateful-probabilistic computation selected by
  a bit (real versus ideal): a map $\mathrm{Bool} \to \mathsf{SPComp}\,\mathrm{Bool}$.
\end{definition}

n42591.content:
\begin{definition}[Probability of returning true]
  \label{def:prtrue}
  \uses{def:spcomp, def:sdistr}
  \lean{CatCrypt.Crypto.prTrue}
  \leanok
  For a game $G : \mathsf{SPComp}\,\mathrm{Bool}$ and an initial heap $h_0$, the
  probability that $G$ returns $\mathsf{true}$ is the total mass on $\mathsf{true}$
  across all final heaps:
  \[
    \operatorname{Pr}[G \Downarrow \mathsf{true} \mid h_0]
      \;=\; \sum_{h} (G\,h_0)\bigl(\mathsf{some}\,(\mathsf{true}, h)\bigr).
  \]
\end{definition}

n42593.content:
\begin{definition}[Advantage against an adversary]
  \label{def:advantageA}
  \uses{def:advantage, def:spcomp}
  \lean{CatCrypt.Crypto.AdvantageA}
  \leanok
  Given games $G_0, G_1 : \mathsf{SPComp}\,\alpha$ and an adversary
  $A : \alpha \to \mathsf{SPComp}\,\mathrm{Bool}$ that post-processes the game output
  into a guess, the \emph{adversarial advantage} is
  \[
    \mathsf{Adv}^A(G_0, G_1) \;=\; \mathsf{Adv}(G_0 \mathbin{\gg\!=}A,\; G_1 \mathbin{\gg\!=}A).
  \]
\end{definition}

n42594.content:
\begin{theorem}[Triangle inequality for advantage]
  \label{thm:advantageA-triangle}
  \uses{def:advantageA}
  \lean{CatCrypt.Crypto.advantageA_triangle}
  \leanok
  For all games $G_0, G_1, G_2$ and every adversary $A$,
  \[
    \mathsf{Adv}^A(G_0, G_2)
      \;\le\; \mathsf{Adv}^A(G_0, G_1) + \mathsf{Adv}^A(G_1, G_2).
  \]
\end{theorem}

n42595.content:
\begin{theorem}[Factoring a pure prefix]
  \label{thm:advantageA-isPure-bind}
  \uses{def:advantageA}
  \lean{CatCrypt.Crypto.advantageA_isPure_bind}
  \leanok
  Let $\mathit{pfx}$ be a heap-independent (pure) computation. If for every prefix
  value $x$ the continuations satisfy $\mathsf{Adv}^A(f\,x, g\,x) \le \varepsilon$,
  then
  \[
    \mathsf{Adv}^A(\mathit{pfx} \mathbin{\gg\!=}f,\; \mathit{pfx} \mathbin{\gg\!=}g)
      \;\le\; \varepsilon.
  \]
\end{theorem}

n42596.content:
\begin{theorem}[Factoring a uniform-sampling prefix]
  \label{thm:advantageA-sample-bind}
  \uses{def:advantageA}
  \lean{CatCrypt.Crypto.advantageA_sample_bind}
  \leanok
  For a finite nonempty type $\alpha$, if
  $\mathsf{Adv}^A(f\,x, g\,x) \le \varepsilon$ for every sampled value $x$, then
  sampling a shared uniform prefix preserves the bound:
  \[
    \mathsf{Adv}^A\!\bigl(\mathsf{sample}\,\alpha \mathbin{\gg\!=}f,\;
      \mathsf{sample}\,\alpha \mathbin{\gg\!=}g\bigr) \;\le\; \varepsilon.
  \]
\end{theorem}

n42597.content:
\begin{definition}[Unsigned difference]
  \label{def:absdiff}
  \lean{CatCrypt.Crypto.absDiff}
  \leanok
  The unsigned difference in $\mathbb{R}_{\ge 0}^{\infty}$ is
  $\mathsf{absDiff}(a, b) = (a - b) \sqcup (b - a)$, using truncated subtraction.
\end{definition}

n42598.content:
\begin{lemma}[Triangle inequality for the unsigned difference]
  \label{lem:absdiff-triangle}
  \uses{def:absdiff}
  \lean{CatCrypt.Crypto.absDiff_triangle}
  \leanok
  $\mathsf{absDiff}(a, c) \le \mathsf{absDiff}(a, b) + \mathsf{absDiff}(b, c)$.
\end{lemma}

n42599.content:
\begin{definition}[Statistical distance]
  \label{def:sdist}
  \uses{def:absdiff, def:prtrue, def:spcomp}
  \lean{CatCrypt.Crypto.sdist}
  \leanok
  The \emph{statistical distance} between Kleisli morphisms
  $f, g : \alpha \to \mathsf{SPComp}\,\beta$ is the supremum, over all
  distinguishers $D$, inputs $a$, and initial heaps $h_0$, of the difference in
  acceptance probability:
  \[
    \mathsf{sdist}(f, g)
      \;=\; \bigsqcup_{D, a, h_0}
        \mathsf{absDiff}\bigl(
          \operatorname{Pr}[f\,a \mathbin{\gg\!=}D \Downarrow \mathsf{true} \mid h_0],\;
          \operatorname{Pr}[g\,a \mathbin{\gg\!=}D \Downarrow \mathsf{true} \mid h_0]\bigr).
  \]
  Unlike $\mathsf{Adv}$, it maximizes over every initial heap, so the adversary
  may choose the starting state.
\end{definition}

n42602.content:
\begin{theorem}[Right post-processing lemma]
  \label{thm:sdist-comp-right}
  \uses{def:sdist}
  \lean{CatCrypt.Crypto.sdist_comp_right}
  \leanok
  Post-composition with a shared continuation $g$ does not increase distance:
  \[
    \mathsf{sdist}\bigl(a \mapsto f_1\,a \mathbin{\gg\!=}g,\; a \mapsto f_2\,a \mathbin{\gg\!=}g\bigr)
      \;\le\; \mathsf{sdist}(f_1, f_2).
  \]
\end{theorem}

n42603.content:
\begin{theorem}[Left post-processing lemma]
  \label{thm:sdist-comp-left}
  \uses{def:sdist}
  \lean{CatCrypt.Crypto.sdist_comp_left}
  \leanok
  Pre-composition with a shared prefix $f$ does not increase distance:
  \[
    \mathsf{sdist}\bigl(a \mapsto f\,a \mathbin{\gg\!=}g_1,\; a \mapsto f\,a \mathbin{\gg\!=}g_2\bigr)
      \;\le\; \mathsf{sdist}(g_1, g_2).
  \]
\end{theorem}

n42604.content:
\begin{theorem}[Composition of $\varepsilon$-close morphisms]
  \label{thm:sdist-comp-add}
  \uses{thm:sdist-comp-right, thm:sdist-comp-left}
  \lean{CatCrypt.Crypto.sdist_comp_add}
  \leanok
  If $\mathsf{sdist}(f_1, f_2) \le \varepsilon_1$ and
  $\mathsf{sdist}(g_1, g_2) \le \varepsilon_2$, then the composites are
  $(\varepsilon_1 + \varepsilon_2)$-close:
  \[
    \mathsf{sdist}\bigl(a \mapsto f_1\,a \mathbin{\gg\!=}g_1,\;
      a \mapsto f_2\,a \mathbin{\gg\!=}g_2\bigr) \;\le\; \varepsilon_1 + \varepsilon_2.
  \]
  This makes $\mathsf{sdist}$-bounded pairs the morphisms of a wide sub-SMC of the
  Kleisli category, the semantic foundation of game hopping.
\end{theorem}

n42605.content:
\begin{theorem}[Advantage bounds statistical distance for pure games]
  \label{thm:sdist-isPure-le}
  \uses{def:sdist, def:advantage}
  \lean{CatCrypt.Crypto.sdist_isPure_le}
  \leanok
  If $f$ and $g$ are pointwise heap-independent and, for every distinguisher $D$
  and input $a$, the empty-heap unsigned difference is bounded by $\varepsilon$,
  then $\mathsf{sdist}(f, g) \le \varepsilon$. Purity lets the empty-heap bound be
  promoted to the all-heap supremum by shifting the heap into the distinguisher.
\end{theorem}

n42606.content:
\begin{theorem}[Statistical distance from per-input advantage]
  \label{thm:sdist-of-isPure-advantageA}
  \uses{thm:sdist-isPure-le, def:advantageA}
  \lean{CatCrypt.Crypto.sdist_of_isPure_advantageA}
  \leanok
  For pointwise-pure $f, g$: if
  $\mathsf{Adv}^D(f\,a, g\,a) \le \varepsilon$ for every input $a$ and distinguisher
  $D$, then $\mathsf{sdist}(f, g) \le \varepsilon$. This matches the argument order
  of security definitions and is the common bridge in protocol proofs.
\end{theorem}

n42607.content:
\begin{theorem}[Statistical distance for oracle games]
  \label{thm:sdist-oracleGame-le}
  \uses{def:sdist, def:advantage}
  \lean{CatCrypt.Crypto.sdist_oracleGame_le}
  \leanok
  Suppose $G_{\mathrm{real}}\,A = A\,o_{\mathrm{real}}$ and
  $G_{\mathrm{ideal}}\,A = A\,o_{\mathrm{ideal}}$ hand the adversary an oracle record.
  If $\mathsf{Adv}(G_{\mathrm{real}}\,A, G_{\mathrm{ideal}}\,A) \le \varepsilon$ for
  every $A$, then $\mathsf{sdist}(G_{\mathrm{real}}, G_{\mathrm{ideal}}) \le \varepsilon$.
  The distinguisher and the initial heap are both absorbed into the adversary.
\end{theorem}

n42608.content:
\begin{theorem}[Dependent hybrid bound]
  \label{thm:advantage-hybrid-dep}
  \uses{def:advantageA, thm:advantageA-triangle}
  \lean{CatCrypt.Crypto.HybridArgument.advantage_hybrid_dep}
  \leanok
  For a sequence of games $G : \mathbb{N} \to \mathsf{SPComp}\,\alpha$ and an
  adversary $A$, the advantage between endpoints is bounded by the sum of per-step
  advantages:
  \[
    \mathsf{Adv}^A(G_0, G_n)
      \;\le\; \sum_{i < n} \mathsf{Adv}^A(G_i, G_{i+1}).
  \]
\end{theorem}

n42609.content:
\begin{theorem}[Uniform hybrid bound]
  \label{thm:advantage-hybrid-uniform}
  \uses{thm:advantage-hybrid-dep}
  \lean{CatCrypt.Crypto.HybridArgument.advantage_hybrid_uniform}
  \leanok
  If every step satisfies $\mathsf{Adv}^A(G_i, G_{i+1}) \le \varepsilon$ for $i < n$,
  then $\mathsf{Adv}^A(G_0, G_n) \le n \cdot \varepsilon$.
\end{theorem}

n42610.content:
\begin{theorem}[Hybrid with perfect steps]
  \label{thm:advantage-hybrid-zero}
  \uses{thm:advantage-hybrid-uniform, thm:advantage-zero-of-rhoare}
  \lean{CatCrypt.Crypto.HybridArgument.advantage_hybrid_zero}
  \leanok
  If every adjacent pair $G_i, G_{i+1}$ is perfectly indistinguishable (related by
  $\mathsf{rHoare}\;\mathsf{eqPre}\;\cdot\;\cdot\;\mathsf{eqPost}$), then the total
  advantage vanishes: $\mathsf{Adv}^A(G_0, G_n) = 0$.
\end{theorem}

n42611.content:
\begin{theorem}[Factored hybrid bound]
  \label{thm:advantage-hybrid-factored}
  \uses{thm:advantage-factorization, thm:advantage-hybrid-uniform}
  \lean{CatCrypt.Crypto.HybridArgument.advantage_hybrid_factored}
  \leanok
  When real and ideal games share a common post-processing $f$, and each base step
  is bounded by $\varepsilon$ against the folded adversary $x \mapsto f\,x \mathbin{\gg\!=}A$,
  then
  \[
    \mathsf{Adv}^A\!\bigl((G_{\mathrm{base}}\,0) \mathbin{\gg\!=}f,\;
      (G_{\mathrm{base}}\,n) \mathbin{\gg\!=}f\bigr) \;\le\; n \cdot \varepsilon.
  \]
\end{theorem}

n42612.content:
\begin{definition}[Symmetric encryption scheme]
  \label{def:encscheme}
  \uses{def:spcomp}
  \lean{CatCrypt.Crypto.EncScheme}
  \leanok
  An \emph{encryption scheme} bundles key, plaintext, and ciphertext types (keys and
  ciphertexts finite and nonempty) with probabilistic algorithms: key generation
  $\mathsf{keyGen} : \mathsf{SPComp}\,\mathrm{Key}$, encryption
  $\mathsf{encrypt} : \mathrm{Key} \to \mathrm{Plaintext} \to \mathsf{SPComp}\,\mathrm{Ciphertext}$,
  and decryption
  $\mathsf{decrypt} : \mathrm{Key} \to \mathrm{Ciphertext} \to \mathsf{SPComp}\,(\mathrm{Option}\,\mathrm{Plaintext})$.
\end{definition}

n42613.content:
\begin{definition}[Correctness]
  \label{def:enc-correct}
  \uses{def:encscheme}
  \lean{CatCrypt.Crypto.EncScheme.Correct}
  \leanok
  A scheme is \emph{correct} if decryption recovers the message on every reachable
  path: for all $k, m, h$, whenever $(c, h')$ is in the support of
  $\mathsf{encrypt}\,k\,m\,h$ and $(\mathit{result}, h'')$ is in the support of
  $\mathsf{decrypt}\,k\,c\,h'$, then $\mathit{result} = \mathsf{some}\,m$.
\end{definition}

n42614.content:
\begin{definition}[IND-CPA game]
  \label{def:indcpa-game}
  \uses{def:encscheme}
  \lean{CatCrypt.Crypto.SecurityDefs.INDCPA_Game}
  \leanok
  The IND-CPA game generates a fresh key and encrypts one of two adversary-chosen
  messages, selected by the challenge bit:
  \[
    \mathsf{INDCPA}(E, m_0, m_1, b) \;=\;
      k \gets E.\mathsf{keyGen};\; E.\mathsf{encrypt}\,k\,(\text{if } b \text{ then } m_0 \text{ else } m_1).
  \]
\end{definition}

n42615.content:
\begin{definition}[IND-CPA advantage]
  \label{def:indcpa-adv}
  \uses{def:indcpa-game, def:advantageA}
  \lean{CatCrypt.Crypto.SecurityDefs.INDCPA_Adv}
  \leanok
  The IND-CPA advantage of $A$ is the adversarial advantage between the two
  challenge bits:
  \[
    \mathsf{INDCPA\text{-}Adv}(E, m_0, m_1, A)
      \;=\; \mathsf{Adv}^A\!\bigl(\mathsf{INDCPA}(E, m_0, m_1, \mathsf{true}),\;
        \mathsf{INDCPA}(E, m_0, m_1, \mathsf{false})\bigr).
  \]
\end{definition}

n42616.content:
\begin{definition}[Pseudorandom function family]
  \label{def:prfscheme}
  \lean{CatCrypt.Crypto.SecurityDefs.PRFScheme}
  \leanok
  A \emph{PRF family} bundles finite nonempty key and output types, an input type,
  and an evaluation function $\mathsf{eval} : \mathrm{Key} \to \mathrm{Input} \to \mathrm{Output}$.
\end{definition}

n42618.content:
\begin{definition}[Message authentication code]
  \label{def:macscheme}
  \lean{CatCrypt.Crypto.SecurityDefs.MACScheme}
  \leanok
  A \emph{MAC scheme} bundles finite nonempty key and tag types (tags with decidable
  equality), a message type, a tag function $\mathsf{mac} : \mathrm{Key} \to \mathrm{Message} \to \mathrm{Tag}$,
  and a verifier $\mathsf{verify}$ that by default recomputes and compares the tag.
\end{definition}

n42619.content:
\begin{definition}[EUF-CMA advantage]
  \label{def:eufcma-adv}
  \uses{def:macscheme, def:prtrue}
  \lean{CatCrypt.Crypto.SecurityDefs.EUF_CMA_Adv}
  \leanok
  In the single-query EUF-CMA game, the adversary sees a tag on a message $m$ and
  submits a forgery $(m^{*}, t^{*})$; the game returns whether the forgery verifies.
  The advantage is the acceptance probability of the forgery composed with the
  adversary:
  \[
    \mathsf{EUF\text{-}CMA\text{-}Adv}(M, m, m^{*}, t^{*}, A)
      \;=\; \operatorname{Pr}[\mathsf{EUF\_CMA\_Real}\,M\,m\,m^{*}\,t^{*} \mathbin{\gg\!=}A \Downarrow \mathsf{true}
        \mid \mathrm{Heap.empty}].
  \]
\end{definition}

n42620.content:
\begin{lemma}[Monotonicity of lifting]
  \label{lem:liftr-mono}
  \uses{def:liftr}
  \lean{CatCrypt.Prob.liftR_mono}
  \leanok
  If $R \subseteq S$ pointwise (i.e.\ $R\,a\,b \to S\,a\,b$ for all $a,b$) and
  $d_1 \mathrel{\sim}{R} d_2$, then $d_1 \mathrel{\sim}{S} d_2$.
\end{lemma}

n42621.content:
\begin{lemma}[Symmetry of lifting]
  \label{lem:liftr-symm}
  \uses{def:liftr}
  \lean{CatCrypt.Prob.liftR_symm}
  \leanok
  If $d_1 \mathrel{\sim}{R} d_2$, then $d_2 \mathrel{\sim}{R^{-1}} d_1$, where
  $R^{-1}\,b\,a := R\,a\,b$; the witnessing coupling is obtained by swapping the
  two coordinates of the joint distribution.
\end{lemma}

n42622.content:
\begin{lemma}[Equality coupling forces equality]
  \label{lem:liftr-eq-implies-eq}
  \uses{def:liftr}
  \lean{CatCrypt.Prob.liftR_eq_implies_eq}
  \leanok
  If $d_1 \mathrel{\sim}{(=)} d_2$, then $d_1 = d_2$. An equality coupling places all
  mass on the diagonal, so both marginal sums collapse to the same diagonal
  values.
\end{lemma}

n42623.content:
\begin{definition}[Relational precondition]
  \label{def:rpre}
  \lean{CatCrypt.Relational.RPre}
  \leanok
  A \emph{relational precondition} $\operatorname{RPre}$ is a predicate on pairs of heaps,
  $\operatorname{Heap}\to \operatorname{Heap}\to \mathsf{Prop}$.
\end{definition}

n42624.content:
\begin{definition}[Relational postcondition]
  \label{def:rpost}
  \lean{CatCrypt.Relational.RPost}
  \leanok
  A \emph{relational postcondition} $\operatorname{RPost}\,\alpha\,\beta$ is a predicate
  relating two result--heap pairs,
  $\alpha \to \operatorname{Heap}\to \beta \to \operatorname{Heap}\to \mathsf{Prop}$.
\end{definition}

n42625.content:
\begin{definition}[Equality precondition]
  \label{def:eqpre}
  \uses{def:rpre}
  \lean{CatCrypt.Relational.eqPre}
  \leanok
  The equality precondition $\operatorname{eqPre}$ holds of $(h_1,h_2)$ exactly when
  $h_1 = h_2$.
\end{definition}

n42626.content:
\begin{definition}[Equality postcondition]
  \label{def:eqpost}
  \uses{def:rpost}
  \lean{CatCrypt.Relational.eqPost}
  \leanok
  The equality postcondition $\operatorname{eqPost}$ relates $(a_1,h_1)$ and $(a_2,h_2)$ when
  both the results and the heaps agree, $a_1 = a_2 \wedge h_1 = h_2$.
\end{definition}

n42629.content:
\begin{theorem}[Symmetry]
  \label{thm:rhoare-symm}
  \uses{def:rhoare,lem:liftr-symm}
  \lean{CatCrypt.Relational.rHoare_symm}
  \leanok
  The judgment is symmetric: from
  $\{\,\}\;( \sim \lambda \;\{h\}_1\,h_2.\ \Phi\,h_2\,h_1)\,c_2\,c_1\,(\lambda a_2\,h_2\,a_1\,h_1.\ \Psi\,a_1\,h_1\,a_2\,h_2)$
  one derives $\{\,\}\;\Phi \sim \,\;\{c\}_1\,c_2\,\Psi$.
\end{theorem}

n42630.content:
\begin{theorem}[Sequential composition / bind]
  \label{thm:rhoare-bind}
  \uses{def:rhoare,thm:liftr-bind}
  \lean{CatCrypt.Relational.rHoare_bind}
  \leanok
  Suppose $\{\,\}\;\Phi \sim \,\;\{c\}_1\,c_2\,\Psi$ and, for all $a,b$,
  $\{\,\}\;( \sim \lambda \;\{h\}_1\,h_2.\ \Psi\,a\,h_1\,b\,h_2)\,(f_1\,a)\,(f_2\,b)\,\Theta$.
  Then
  \[
    \{\,\}\;\Phi \sim \,\;\{(\}c_1 \mathbin{\gg\!=}f_1)\,(c_2 \mathbin{\gg\!=}f_2)\,\Theta .
  \]
\end{theorem}

n42631.content:
\begin{theorem}[Reflexivity]
  \label{thm:rhoare-refl}
  \uses{def:rhoare,def:eqpre,def:eqpost,lem:liftr-refl}
  \lean{CatCrypt.Relational.rHoare_refl}
  \leanok
  Every program is related to itself under equality: for all $c$,
  $\{\,\}\;\operatorname{eqPre}\sim \,\;\{c\}\,c\,\operatorname{eqPost}$.
\end{theorem}

n42632.content:
\begin{theorem}[Synchronized sampling, diagonal coupling]
  \label{thm:rhoare-sample-same}
  \uses{def:rhoare,thm:liftr-bind,lem:liftr-refl}
  \lean{CatCrypt.Relational.rHoare_sample_same}
  \leanok
  Sampling the same finite nonempty type on both sides with the diagonal
  coupling yields equal samples:
  \[
    \{\,\}\;\Phi \sim \,\;\{(\}\mathsf{sample}\,\alpha)\,(\mathsf{sample}\,\alpha)\,
      (\lambda a_1\,h_1\,a_2\,h_2.\ \Phi\,h_1\,h_2 \wedge a_1 = a_2).
  \]
\end{theorem}

n42633.content:
\begin{theorem}[Bijection sampling]
  \label{thm:rhoare-sample-bij}
  \uses{def:rhoare,thm:liftr-bind,lem:liftr-uniform-bij}
  \lean{CatCrypt.Relational.rHoare_sample_bij}
  \leanok
  Sampling along a bijection $f : \alpha \simeq \beta$ relates the two samples by
  $f$:
  \[
    \{\,\}\;\Phi \sim \,\;\{(\}\mathsf{sample}\,\alpha)\,(\mathsf{sample}\,\beta)\,
      (\lambda a\,h_1\,b\,h_2.\ \Phi\,h_1\,h_2 \wedge f\,a = b).
  \]
\end{theorem}

n42634.content:
\begin{theorem}[Frame]
  \label{thm:r-frame}
  \uses{def:rhoare,lem:liftr-mono}
  \lean{CatCrypt.Relational.r_frame}
  \leanok
  If $\{\,\}\;\Phi \sim \,\;\{c\}_1\,c_2\,\Theta$ and the frame $\Psi$ follows from the
  postcondition ($\Theta\,a\,h_1\,b\,h_2 \to \Psi\,h_1\,h_2$), then the frame may
  be carried alongside:
  \[
    \{\,\}\;( \sim \Phi \;\{\wedge \}\Psi)\,c_1\,c_2\,(\lambda a\,h_1\,b\,h_2.\ \Theta\,a\,h_1\,b\,h_2 \wedge \Psi\,h_1\,h_2).
  \]
\end{theorem}

n42635.content:
\begin{definition}[Assertion locality]
  \label{def:depends-on}
  \uses{def:rpre}
  \lean{CatCrypt.Relational.DependsOn}
  \leanok
  $\operatorname{DependsOn}\,P\,L$ holds when the assertion $P$ only inspects locations in the
  set $L$: whenever two heap pairs agree on all locations of $L$, $P$ cannot
  distinguish them.
\end{definition}

n42636.content:
\begin{definition}[Computation footprint]
  \label{def:preserves-outside}
  \uses{def:spcomp}
  \lean{CatCrypt.Relational.PreservesOutside}
  \leanok
  $\operatorname{PreservesOutside}\,c\,L$ holds when $c$ never modifies locations outside $L$:
  for every output $(a,h')$ in the support of $c\,h$ and every $\mathit{id} \notin L$,
  the value of $\mathit{id}$ in $h'$ equals its value in $h$.
\end{definition}

n42638.content:
\begin{theorem}[Reorder a pure prefix on the left]
  \label{thm:rhoare-reorder-pure-l}
  \uses{def:rhoare}
  \lean{CatCrypt.Relational.rHoare_reorder_pure_l}
  \leanok
  If $c$ is heap-independent ($\mathsf{IsPure}\,c$), the pure operation may be
  commuted past an independent computation $d$ on the left side:
  from a judgment for $d \mathbin{\gg\!=}(\lambda y.\ c \mathbin{\gg\!=}(\lambda x.\ k\,x\,y))$ one
  obtains the judgment for $c \mathbin{\gg\!=}(\lambda x.\ d \mathbin{\gg\!=}(\lambda y.\ k\,x\,y))$
  against the same right side.
\end{theorem}

n42639.content:
\begin{theorem}[Swap two samples in opposite order]
  \label{thm:rhoare-sample-comm}
  \uses{def:rhoare,thm:liftr-bind,lem:liftr-refl}
  \lean{CatCrypt.Relational.rHoare_sample_comm}
  \leanok
  When the left side samples $\alpha$ then $\beta$ and the right side samples
  $\beta$ then $\alpha$, the two orders may be aligned: if
  $\{\,\}\;\Phi \sim \,\;\{(\}k_1\,a\,b)\,(k_2\,a\,b)\,\Psi$ for all $a,b$, then the
  differently-ordered sampling programs are related under $\Phi$ and $\Psi$.
\end{theorem}

n42640.content:
\begin{theorem}[Zero advantage from pRHL equality]
  \label{thm:advantage-zero-of-rhoare}
  \uses{def:rhoare,def:eqpre,def:eqpost,lem:liftr-eq-implies-eq,def:advantageA}
  \lean{CatCrypt.Crypto.advantage_zero_of_rHoare}
  \leanok
  If $\{\,\}\;\operatorname{eqPre}\sim \,\;\{G\}_0\,G_1\,\operatorname{eqPost}$, then no adversary can distinguish the
  two games: for every $A$, $\operatorname{Adv}\,G_0\,G_1\,A = 0$. The equality
  postcondition forces the empty-heap output distributions to coincide.
\end{theorem}

n42642.content:
\begin{theorem}[Factorization with a commuted pure prefix]
  \label{thm:advantage-factorization-comm}
  \uses{def:advantageA,thm:advantage-factorization}
  \lean{CatCrypt.Relational.advantage_factorization_comm}
  \leanok
  When both games share a pure prefix $\mathit{pfx}$, it may be commuted past the
  varying parts and factored into the distinguisher: for $\mathsf{IsPure}\,\mathit{pfx}$,
  \[
    \operatorname{Adv}\,(\mathit{pfx} \mathbin{\gg\!=}\lambda p.\ G_1 \mathbin{\gg\!=}\lambda r.\ k\,p\,r)\,
                 (\mathit{pfx} \mathbin{\gg\!=}\lambda p.\ G_2 \mathbin{\gg\!=}\lambda r.\ k\,p\,r)\,A
    = \operatorname{Adv}\,G_1\,G_2\,(\lambda r.\ \mathit{pfx} \mathbin{\gg\!=}\lambda p.\ (k\,p\,r) \mathbin{\gg\!=}A).
  \]
\end{theorem}

n42643.content:
\begin{theorem}[Symmetry of advantage]
  \label{thm:advantage-symm}
  \uses{def:advantage}
  \lean{CatCrypt.Relational.advantage_symm}
  \leanok
  The distinguishing advantage is symmetric in its two games:
  $\operatorname{Adv}\,G_1\,G_2 = \operatorname{Adv}\,G_2\,G_1$.
\end{theorem}

n42644.content:
\begin{definition}[Operation signature]
  \label{def:opsig}
  \lean{CatCrypt.Package.OpSig}
  \leanok
  An \emph{operation signature} $\mathsf{OpSig}$ is a pair of types
  $(\mathsf{src}, \mathsf{tgt})$: the input and output type of a single oracle
  operation.
\end{definition}

n42645.content:
\begin{definition}[Interface]
  \label{def:interface}
  \uses{def:opsig}
  \lean{CatCrypt.Package.Interface}
  \leanok
  An \emph{interface} is a finite set of entries, each pairing an operation
  identifier $\mathrm{id} \in \mathbb{N}$ with a signature, subject to
  uniqueness of identifiers. Interfaces carry an empty interface, a membership
  predicate $\mathsf{has}\,I\,\mathrm{id}\,S\,T$, a disjointness relation, and a
  union of identifier-disjoint interfaces.
\end{definition}

n42646.content:
\begin{definition}[Typed function]
  \label{def:typedfun}
  \uses{def:spcomp}
  \lean{CatCrypt.Package.TypedFun}
  \leanok
  A \emph{typed function} bundles an input type $\mathsf{src}$, an output type
  $\mathsf{tgt}$, and an implementation $\mathsf{impl} : \mathsf{src} \to
  \mathsf{SPComp}\,\mathsf{tgt}$. These implementations are oracle-free: they
  are ordinary stateful-probabilistic computations with nothing left to
  substitute.
\end{definition}

n42647.content:
\begin{definition}[Raw package]
  \label{def:rawpackage}
  \uses{def:typedfun}
  \lean{CatCrypt.Package.RawPackage}
  \leanok
  A \emph{raw package} is a finite set of package entries, each pairing an
  operation identifier with a typed function, again with unique identifiers. It
  carries $\mathsf{ids}$, $\mathsf{has}$, $\mathsf{lookup}$, a $\mathsf{singleton}$
  constructor, and an empty package.
\end{definition}

n42648.content:
\begin{definition}[Parallel composition of raw packages]
  \label{def:rawpackage-par}
  \uses{def:rawpackage}
  \lean{CatCrypt.Package.RawPackage.par}
  \leanok
  For identifier-disjoint packages $P_1, P_2$, the parallel composition
  $\mathsf{par}\,P_1\,P_2$ is the union of their entries; disjointness of
  identifiers guarantees the uniqueness invariant.
\end{definition}

n42649.content:
\begin{definition}[Resolving an operation]
  \label{def:rawpackage-resolve}
  \uses{def:rawpackage, def:spcomp}
  \lean{CatCrypt.Package.RawPackage.resolve}
  \leanok
  $\mathsf{resolve}\,P\,\mathrm{id}\,x$ looks up the implementation of
  operation $\mathrm{id}$, checks that the stored source and target types match
  the requested ones, and calls it; if the operation is absent or the types
  mismatch it returns $\mathsf{SPComp.fail}$. This is how a shallow package is
  run.
\end{definition}

n42650.content:
\begin{definition}[Linking of raw packages is a stub]
  \label{def:rawpackage-link}
  \uses{def:rawpackage}
  \lean{CatCrypt.Package.RawPackage.link}
  \leanok
  $\mathsf{link}\,P_1\,P_2 = P_1$ is a \emph{shallow-layer no-op stub}. Because
  $\mathsf{RawPackage}$ stores oracle-free typed functions, there are no oracle
  calls to substitute, so linking has nothing to do. Oracle-substituting
  linking is defined in the deep embedding
  (Definition~\ref{def:deeppackage-link}) and proved correct and associative by
  Theorems~\ref{thm:runpkg-link} and~\ref{thm:runpkg-link-assoc}.
\end{definition}

n42651.content:
\begin{definition}[Kleisli category of $\mathsf{SPComp}$]
  \label{def:klspcomp}
  \uses{def:spcomp, def:spcomp-ops}
  \lean{CatCrypt.Core.KlSPComp}
  \leanok
  $\mathsf{KlSPComp}$ is the type of objects of the Kleisli category of
  $\mathsf{SPComp}$ (an opaque copy of $\mathsf{Type}$). A morphism $\alpha \to
  \beta$ is a function $\alpha \to \mathsf{SPComp}\,\beta$; identity is
  $\mathsf{pure}$ and composition is $\mathsf{bind}$. The category laws are the
  monad laws (Lemmas~\ref{lem:pure-bind}, \ref{lem:bind-pure},
  \ref{lem:bind-assoc}). With $\mathrm{Sum}$ as tensor and $\mathrm{Empty}$ as
  unit, $\mathsf{KlSPComp}$ is a symmetric monoidal category.
\end{definition}

n42653.content:
\begin{definition}[Cocartesian monoidal category]
  \label{def:cocartesian-class}
  \lean{CategoryTheory.CocartesianMonoidalCategory}
  \leanok
  A monoidal category is \emph{cocartesian} when its unit is initial and its
  tensor is the categorical binary coproduct (the dual of a cartesian monoidal
  category). It provides coprojections $\mathsf{inl}, \mathsf{inr}$ and a
  copairing $\mathsf{desc}$ with the expected universal property.
\end{definition}

n42654.content:
\begin{definition}[Copairing in $\mathsf{KlSPComp}$]
  \label{def:klspcomp-codesc}
  \uses{def:klspcomp}
  \lean{CatCrypt.Core.KlSPComp.klDesc}
  \leanok
  Given $f : \alpha \to \gamma$ and $g : \beta \to \gamma$ in
  $\mathsf{KlSPComp}$, the copairing $\mathsf{klDesc}\,f\,g$ maps
  $\mathrm{inl}\,a \mapsto f\,a$ and $\mathrm{inr}\,b \mapsto g\,b$. The
  coprojections $\mathsf{klInl}, \mathsf{klInr}$ embed a summand via
  $\mathsf{pure}$.
\end{definition}

n42655.content:
\begin{proposition}[$\mathsf{KlSPComp}$ is cocartesian]
  \label{prop:klspcomp-cocartesian}
  \uses{def:cocartesian-class, def:klspcomp-codesc}
  \lean{CatCrypt.Core.KlSPComp.binaryCoproductIsColimit}
  \leanok
  The cofan $\mathrm{BinaryCofan}(\mathsf{klInl}, \mathsf{klInr})$ is a colimit:
  $\mathrm{Sum}$ is the coproduct in $\mathsf{KlSPComp}$, with $\mathrm{Empty}$
  initial. Hence $\mathsf{KlSPComp}$ is a cocartesian monoidal category.
\end{proposition}

n42656.content:
\begin{definition}[Affine monoidal category]
  \label{def:affine-class}
  \lean{CategoryTheory.AffineMonoidalCategory}
  \leanok
  An \emph{affine} monoidal category equips every object with a natural discard
  morphism $\mathsf{del}\,X : X \to \mathbf{1}$ satisfying $\mathsf{del}\,
  \mathbf{1} = \mathrm{id}$ and naturality $f \mathbin{;\!;}\mathsf{del}\,Y =
  \mathsf{del}\,X$. Every computation can be discarded.
\end{definition}

n42657.content:
\begin{definition}[Discard in $\mathsf{KlSPComp}$]
  \label{def:klspcomp-del}
  \uses{def:affine-class, def:klspcomp}
  \lean{CatCrypt.Core.KlSPComp.klDel}
  \leanok
  The discard morphism $\mathsf{klDel}\,\alpha : \alpha \to \mathrm{Empty}$
  sends every value to the failing computation $\mathsf{SPComp.fail}$. This
  makes $\mathsf{KlSPComp}$ an affine monoidal category.
\end{definition}

n42659.content:
\begin{definition}[Package interface]
  \label{def:pkginterface}
  \uses{def:klspcomp}
  \lean{CatCrypt.Category.PkgInterface}
  \leanok
  A \emph{package interface} $I$ is an index type $\iota$ together with domain
  and codomain families $\mathsf{doms}, \mathsf{codoms} : \iota \to
  \mathsf{KlSPComp}$. It presents domain and codomain objects
  $\mathsf{domFam}\,I, \mathsf{codomFam}\,I$ in $\mathsf{FamObj}\,
  \mathsf{KlSPComp}$. Parallel combination $\mathsf{tensor}$ (via $\mathrm{Sum}$)
  and the empty interface $\mathsf{unit}$ agree definitionally with the family
  tensor and unit.
\end{definition}

n42660.content:
\begin{definition}[Package implementation]
  \label{def:pkgimpl}
  \uses{def:pkginterface, def:famobj}
  \lean{CatCrypt.Category.PkgImpl}
  \leanok
  A \emph{package implementation} of interface $I$ is a morphism
  $\mathsf{domFam}\,I \to \mathsf{codomFam}\,I$ in
  $\mathsf{FamObj}\,\mathsf{KlSPComp}$: an index permutation together with, for
  each operation $i$, a Kleisli arrow $\mathsf{doms}\,i \to
  \mathsf{SPComp}(\mathsf{codoms}(\sigma\,i))$.
\end{definition}

n42661.content:
\begin{definition}[Kleisli linking of package implementations]
  \label{def:pkgimpl-link}
  \uses{def:pkgimpl}
  \lean{CatCrypt.Category.PkgImpl.link}
  \leanok
  Linking $\mathsf{link}\,p_1\,p_2 = p_1 \mathbin{;\!;}p_2$ is composition in
  $\mathsf{FamObj}\,\mathsf{KlSPComp}$. At each operation it computes as
  $\mathsf{bind}\,(p_1.\mathsf{map}\,i\,x)\,(p_2.\mathsf{map}(p_1.\sigma\,i))$:
  a first-order \emph{data pipeline} (run $p_1$, feed the result to $p_2$),
  \emph{not} second-order oracle substitution. Cryptographic package linking is
  the oracle-resolving $\mathsf{DeepPackage.link}$
  (Definition~\ref{def:deeppackage-link}).
\end{definition}

n42662.content:
\begin{definition}[Parallel composition of package implementations]
  \label{def:pkgimpl-par}
  \uses{def:pkgimpl, def:famobj}
  \lean{CatCrypt.Category.PkgImpl.par}
  \leanok
  $\mathsf{par}\,p_1\,p_2 = p_1 \otimes p_2$ is the family tensor of the two
  implementations. It dispatches an operation $\mathrm{inl}\,i$ to $p_1$ and
  $\mathrm{inr}\,j$ to $p_2$. This is parallel composition proper, shared with
  the package category, and inherits the symmetric monoidal laws from
  $\mathsf{FamObj}$.
\end{definition}

n42663.content:
\begin{definition}[Bridge from deep interfaces to package interfaces]
  \label{def:deepinterface-topkg}
  \uses{def:pkginterface, def:deepinterface}
  \lean{CatCrypt.Category.DeepInterface.toPkgInterface}
  \leanok
  A list-based $\mathsf{DeepInterface}$ becomes a family-based
  $\mathsf{PkgInterface}$ by $\mathrm{Fin}$-indexing its operation list: each
  position becomes an index, with domain and codomain read off the entry.
\end{definition}

n42664.content:
\begin{definition}[Raw code: a free monad]
  \label{def:rawcode}
  \uses{def:spcomp}
  \lean{CatCrypt.Deep.RawCode.inductionOn}
  \leanok
  $\mathsf{RawCode}\,\alpha$ is the free monad of computation syntax trees,
  with constructors $\mathsf{ret}$, $\mathsf{bind}$, $\mathsf{sample}$,
  $\mathsf{get}$, $\mathsf{put}$, $\mathsf{fail}$, $\mathsf{oracleCall}$, and
  $\mathsf{embed}$ (which injects an arbitrary $\mathsf{SPComp}$ value as opaque
  code, expressing completeness). Unlike the shallow layer, oracle calls are
  first-class syntax. The structural recursor $\mathsf{inductionOn}$ enumerates
  these constructors.
\end{definition}

n42665.content:
\begin{definition}[Deep interface]
  \label{def:deepinterface}
  \lean{CatCrypt.Deep.DeepInterface}
  \leanok
  A \emph{deep interface} is a list of operation entries $(\mathrm{id}, \mathrm{dom},
  \mathrm{codom})$ of matching universe. It carries an empty interface, a
  membership predicate $\mathsf{contains}$, and extensionality by the operation
  list.
\end{definition}

n42666.content:
\begin{definition}[Valid code bundle]
  \label{def:validcodebundle}
  \uses{def:rawcode}
  \lean{CatCrypt.Deep.ValidCodeBundle}
  \leanok
  Validity of code is the inductive predicate $\mathsf{ValidCode}\,L$ that every
  $\mathsf{get}/\mathsf{put}$ touches only a location id in the declared set
  $L$. A \emph{valid code bundle} pairs a $\mathsf{RawCode}\,\alpha$ with its
  $\mathsf{ValidCode}\,L$ proof; by proof irrelevance two bundles are equal
  whenever their code is.
\end{definition}

n42667.content:
\begin{definition}[Deep package]
  \label{def:deeppackage}
  \uses{def:deepinterface, def:validcodebundle}
  \lean{CatCrypt.Deep.DeepPackage}
  \leanok
  A \emph{deep package} bundles a finite location set $\mathsf{locs}$, an
  import interface, an export interface, and, for every exported operation, an
  implementation mapping a domain value to a valid code bundle over
  $\mathsf{locs}$. The location invariant makes modular composition and
  separation reasoning sound.
\end{definition}

n42668.content:
\begin{definition}[Separation]
  \label{def:deeppackage-sep}
  \uses{def:deeppackage}
  \lean{CatCrypt.Deep.DeepPackage.sep}
  \leanok
  Two deep packages are \emph{separated}, $\mathsf{sep}\,p_1\,p_2$, when their
  location sets are disjoint. Separated packages cannot interfere with each
  other's state.
\end{definition}

n42669.content:
\begin{definition}[Oracle substitution]
  \label{def:substoracle}
  \uses{def:rawcode}
  \lean{CatCrypt.Deep.RawCode.substOracle}
  \leanok
  $\mathsf{substOracle}\,c\,\mathsf{env}$ recursively replaces every
  $\mathsf{oracleCall}\,\mathrm{op}\,\mathrm{dom}\,\mathrm{codom}\,x$ node in
  $c$ by $\mathsf{env}\,\mathrm{op}\,\mathrm{dom}\,\mathrm{codom}\,x$, leaving
  the other constructors intact. This is the engine of real package linking.
\end{definition}

n42670.content:
\begin{lemma}[Substitution composes]
  \label{lem:substoracle-comp}
  \uses{def:substoracle}
  \lean{CatCrypt.Deep.RawCode.substOracle_comp}
  \leanok
  $(\mathsf{substOracle}\,c\,\mathsf{env}_1)\,\mathsf{substOracle}\,\mathsf{env}_2
  = \mathsf{substOracle}\,c\,(\lambda\,\mathrm{op}\,\mathrm{dom}\,\mathrm{codom}\,x.\,
  \mathsf{substOracle}\,(\mathsf{env}_1\,\mathrm{op}\,\mathrm{dom}\,\mathrm{codom}\,x)\,
  \mathsf{env}_2)$. Double substitution is a single substitution through a
  composed environment.
\end{lemma}

n42671.content:
\begin{lemma}[Substitution is a no-op on oracle-free code]
  \label{lem:substoracle-self}
  \uses{def:substoracle}
  \lean{CatCrypt.Deep.RawCode.substOracle_eq_self}
  \leanok
  If $c$ contains no $\mathsf{oracleCall}$ node (predicate $\mathsf{NoOracleCall}\,c$),
  then $\mathsf{substOracle}\,c\,\mathsf{env} = c$ for every environment. This is
  the foundational lemma for reduction packages, whose non-delegated operations
  never call imports.
\end{lemma}

n42672.content:
\begin{definition}[Deep linking]
  \label{def:deeppackage-link}
  \uses{def:deeppackage, def:substoracle}
  \lean{CatCrypt.Deep.DeepPackage.link}
  \leanok
  $\mathsf{link}\,p_1\,p_2$ connects $p_2$'s exports to $p_1$'s imports. It uses
  the union of locations, imports $p_2$'s imports, exports $p_1$'s exports, and
  implements each exported operation by $\mathsf{substOracle}$ on $p_1$'s code,
  replacing every call to an operation in $p_2$'s exports with $p_2$'s
  implementation (and every other call with $\mathsf{fail}$). This is the real,
  oracle-resolving package linking.
\end{definition}

n42673.content:
\begin{definition}[Deep parallel composition]
  \label{def:deeppackage-par}
  \uses{def:deeppackage, def:deeppackage-sep}
  \lean{CatCrypt.Deep.DeepPackage.par}
  \leanok
  For separated $p_1, p_2$, $\mathsf{par}\,p_1\,p_2$ takes the union of
  locations and the concatenation of import/export interfaces, dispatching each
  exported operation to whichever package declares it. Separation is preserved
  by parallel composition on either side.
\end{definition}

n42674.content:
\begin{definition}[Identity package]
  \label{def:deeppackage-id}
  \uses{def:deeppackage}
  \lean{CatCrypt.Deep.DeepPackage.id}
  \leanok
  $\mathsf{id}\,I$ is the stateless passthrough for interface $I$: it exports
  and imports $I$, and implements each operation by a single
  $\mathsf{oracleCall}$ forwarding the request. It is the unit of linking at the
  evaluation level.
\end{definition}

n42675.content:
\begin{definition}[Evaluation to $\mathsf{SPComp}$]
  \label{def:eval}
  \uses{def:rawcode, def:spcomp}
  \lean{CatCrypt.Deep.RawCode.eval}
  \leanok
  $\mathsf{RawCode.eval}$ interprets a syntax tree as an $\mathsf{SPComp}$
  program, mapping each constructor to the corresponding monad operation and
  sending unresolved $\mathsf{oracleCall}$ nodes to $\mathsf{fail}$; a variant
  $\mathsf{evalWith}$ takes an explicit oracle handler. In the reverse
  direction, an elaboration-time reifier $\mathsf{rawCode\%}$ turns a shallow
  $\mathsf{SPComp}$ program over the six core constructors back into
  $\mathsf{RawCode}$, and the two round-trip up to the monad laws.
\end{definition}

n42676.content:
\begin{lemma}[Substitution commutes with evaluation]
  \label{lem:eval-substoracle}
  \uses{def:substoracle, def:eval}
  \lean{CatCrypt.Deep.eval_substOracle}
  \leanok
  Evaluating $\mathsf{substOracle}\,c\,\mathsf{env}$ equals evaluating $c$ with
  the handler that evaluates each environment entry:
  $(\mathsf{substOracle}\,c\,\mathsf{env}).\mathsf{eval} =
  c.\mathsf{evalWith}(\lambda\ldots.\,(\mathsf{env}\ldots).\mathsf{eval})$. This
  is the bridge that makes syntactic linking semantically correct.
\end{lemma}

n42677.content:
\begin{definition}[Running a deep package]
  \label{def:runpkg}
  \uses{def:deeppackage, def:eval}
  \lean{CatCrypt.Crypto.runPkg}
  \leanok
  $\mathsf{runPkg}\,p$ evaluates the conventional main export
  $(0, \mathrm{Unit}, \mathrm{Bool})$ of a deep package to an
  $\mathsf{SPComp}\,\mathrm{Bool}$ (returning $\mathsf{pure}\,\mathsf{true}$ if
  no such export exists), mirroring the cryptographic convention that an
  adversary's main procedure takes no input and returns a boolean guess.
\end{definition}

n42679.content:
\begin{theorem}[Correctness of linking under evaluation]
  \label{thm:runpkg-link}
  \uses{def:runpkg, def:deeppackage-link, lem:eval-substoracle}
  \lean{CatCrypt.Crypto.runPkg_link}
  \leanok
  $\mathsf{runPkg}(\mathsf{link}\,p_1\,p_2)$ equals evaluating $p_1$'s main
  procedure with the oracle handler that resolves each call through $p_2$'s
  exports (and sends absent operations to $\mathsf{fail}$). Syntactic linking on
  the free monad implements semantic oracle resolution on $\mathsf{SPComp}$.
\end{theorem}

n42680.content:
\begin{theorem}[Associativity of linking under evaluation]
  \label{thm:runpkg-link-assoc}
  \uses{def:runpkg, def:deeppackage-link, lem:substoracle-comp, lem:eval-substoracle}
  \lean{CatCrypt.Crypto.runPkg_link_assoc}
  \leanok
  $\mathsf{runPkg}(\mathsf{link}(\mathsf{link}\,p_1\,p_2)\,p_3) =
  \mathsf{runPkg}(\mathsf{link}\,p_1\,(\mathsf{link}\,p_2\,p_3))$. The two
  packages are not definitionally equal — their oracle environments differ
  structurally — but they agree after evaluation, via $\mathsf{substOracle\_comp}$
  and the fact that $\mathsf{fail}$ substitutes to $\mathsf{fail}$.
\end{theorem}

n42681.content:
\begin{theorem}[Interchange law]
  \label{thm:runpkg-interchange}
  \uses{def:runpkg, def:deeppackage-link, def:deeppackage-par}
  \lean{CatCrypt.Crypto.runPkg_interchange}
  \leanok
  Under an interface-matching condition on the oracle environments,
  \[
    \mathsf{runPkg}\bigl(\mathsf{link}\,(\mathsf{par}\,p_1\,p_2)\,(\mathsf{par}\,p_3\,p_4)\bigr)
    = \mathsf{runPkg}\bigl(\mathsf{par}\,(\mathsf{link}\,p_1\,p_3)\,(\mathsf{link}\,p_2\,p_4)\bigr).
  \]
  Linking after tensoring agrees with tensoring after linking, the exchange law
  that makes packages a (bi)categorical composition structure.
\end{theorem}

n42683.content:
\begin{definition}[Game-based security for deep packages]
  \label{def:nompkgsecure}
  \uses{def:deepnomadv}
  \lean{CatCrypt.Crypto.NomPkgSecure}
  \leanok
  $\mathsf{NomPkgSecure}\,G\,G'\,\varepsilon$ holds when for every adversary
  package $A$, $\mathsf{DeepNomAdvantage}\,G\,G'\,A \le \varepsilon\,A$. The
  bound is adversary-dependent, supporting concrete security; it is reflexive
  at $0$, symmetric, and transitive with pointwise-added bounds via the triangle
  inequality.
\end{definition}

n42685.content:
\begin{definition}[Acceptance probability]
  \label{def:fork-accept-prob}
  \uses{def:forkable-adversary}
  \lean{CatCrypt.Crypto.ForkingLemma.acceptProb}
  \leanok
  The \emph{acceptance probability} of $A$ on input $x$ under predicate
  $\mathsf{accept} : Y \to \mathsf{Bool}$ is
  \[
    \mathrm{acc}(A,x) \;=\;
    \operatorname{Pr}\big[\, c \leftarrow \mathsf{coins}\,x;\;
      e \leftarrow_{\$} R \;:\;
      \mathsf{accept}(\mathsf{respond}\,x\,c\,e) \,\big].
  \]
\end{definition}

n42686.content:
\begin{definition}[Forking algorithm]
  \label{def:fork-alg}
  \uses{def:forkable-adversary}
  \lean{CatCrypt.Crypto.ForkingLemma.forkAlg}
  \leanok
  The \emph{forking algorithm} runs $A$ once to obtain a commitment $c$, then
  samples two independent oracle responses $e_1, e_2 \leftarrow_{\$} R$ and
  replays the response phase on each, returning
  $(c, e_1, y_1, e_2, y_2)$ with $y_i = \mathsf{respond}\,x\,c\,e_i$.
\end{definition}

n42687.content:
\begin{definition}[Fork success probability]
  \label{def:fork-succ-prob}
  \uses{def:fork-alg}
  \lean{CatCrypt.Crypto.ForkingLemma.forkSuccProb}
  \leanok
  The \emph{fork success probability} is the probability that both replayed runs
  accept on distinct oracle responses:
  \[
    \mathrm{frk}(A,x) \;=\;
    \operatorname{Pr}\big[\,\mathsf{accept}\,y_1 \wedge \mathsf{accept}\,y_2 \wedge e_1 \neq e_2\,\big],
  \]
  taken over the forking algorithm.
\end{definition}

n42688.content:
\begin{lemma}[AM--GM for extended non-negative reals]
  \label{lem:ennreal-amgm}
  \lean{CatCrypt.Crypto.ForkingLemma.ennreal_two_mul_le_add_sq}
  \leanok
  For all $a, b \in \overline{\mathbb{R}}_{\geq 0}$,
  \[
    2ab \;\leq\; a^2 + b^2 .
  \]
\end{lemma}

n42689.content:
\begin{lemma}[Jensen's inequality under sub-PMF weights]
  \label{lem:jensen-sub-pmf}
  \uses{lem:ennreal-amgm}
  \lean{CatCrypt.Crypto.ForkingLemma.jensen_sub_pmf_sq}
  \leanok
  Let $w : \iota \to \overline{\mathbb{R}}_{\geq 0}$ with
  $\sum_i w_i \leq 1$ and $f : \iota \to \overline{\mathbb{R}}_{\geq 0}$ with
  $f_i \leq 1$ for all $i$. Then squaring is convex against the weights $w$:
  \[
    \Big(\sum_i w_i\, f_i\Big)^2 \;\leq\; \sum_i w_i\, f_i^{\,2} .
  \]
\end{lemma}

n42690.content:
\begin{definition}[Conditional acceptance probability]
  \label{def:cond-acc-prob}
  \uses{def:forkable-adversary}
  \lean{CatCrypt.Crypto.ForkingLemma.condAccProb}
  \leanok
  Fixing a commitment $c$, the \emph{conditional acceptance probability}
  $\mathrm{acc}_c$ is the probability that a single freshly sampled oracle
  response $e \leftarrow_{\$} R$ makes $\mathsf{respond}\,x\,c\,e$ accept.
\end{definition}

n42691.content:
\begin{definition}[Conditional fork probability]
  \label{def:cond-fork-prob}
  \uses{def:forkable-adversary}
  \lean{CatCrypt.Crypto.ForkingLemma.condForkProb}
  \leanok
  Fixing a commitment $c$, the \emph{conditional fork probability}
  $\mathrm{frk}_c$ is the probability that two independent responses
  $e_1, e_2 \leftarrow_{\$} R$ both accept and are distinct.
\end{definition}

n42692.content:
\begin{lemma}[Exact conditional fork count]
  \label{lem:cond-fork-prob-eq}
  \uses{def:cond-acc-prob, def:cond-fork-prob}
  \lean{CatCrypt.Crypto.ForkingLemma.condForkProb_eq}
  \leanok
  For each fixed commitment $c$, exact counting over $R \times R$ gives
  \[
    \mathrm{frk}_c \;=\; \mathrm{acc}_c^{\,2} \;-\; \frac{\mathrm{acc}_c}{\lvert R\rvert},
  \]
  the off-diagonal accepting pairs divided by $\lvert R\rvert^2$.
\end{lemma}

n42693.content:
\begin{lemma}[Decomposition over commitments]
  \label{lem:fork-decompose}
  \uses{def:fork-accept-prob, def:fork-succ-prob, def:cond-acc-prob, def:cond-fork-prob}
  \lean{CatCrypt.Crypto.ForkingLemma.acceptProb_decompose, CatCrypt.Crypto.ForkingLemma.forkSuccProb_decompose}
  \leanok
  Both $\mathrm{acc}(A,x)$ and $\mathrm{frk}(A,x)$ decompose as weighted sums over
  the commitment PMF: $\mathrm{acc} = \sum_c w_c\,\mathrm{acc}_c$ and
  $\mathrm{frk} = \sum_c w_c\,\mathrm{frk}_c$, where $w_c$ is the probability the
  commit phase outputs $c$.
\end{lemma}

n42694.content:
\begin{theorem}[Forking lemma, $q = 1$]
  \label{thm:fork-success-ge}
  \uses{lem:jensen-sub-pmf, lem:cond-fork-prob-eq, lem:fork-decompose}
  \lean{CatCrypt.Crypto.ForkingLemma.fork_success_ge}
  \leanok
  For every forkable adversary $A$, input $x$, and acceptance predicate,
  \[
    \mathrm{frk}(A,x) \;\geq\;
    \mathrm{acc}(A,x)^2 \;-\; \frac{\mathrm{acc}(A,x)}{\lvert R\rvert}.
  \]
  The bound follows by decomposing over commitments, applying the exact
  conditional identity per commitment, and using Jensen's inequality to move the
  square outside the commitment average.
\end{theorem}

n42695.content:
\begin{definition}[$q$-query forkable adversary]
  \label{def:qforkable-adversary}
  \lean{CatCrypt.Crypto.GeneralForkingLemma.QForkableAdversary}
  \leanok
  A \emph{$q$-query forkable adversary} has a probabilistic commit phase
  $\mathsf{coins} : X \to \mathsf{SPComp}\,C$ and a deterministic response phase
  $\mathsf{respond} : X \to C \to (\mathrm{Fin}\,q \to R) \to \mathrm{Fin}\,q \times Y$
  that, given all $q$ oracle responses, outputs an index identifying the relevant
  query together with its result.
\end{definition}

n42696.content:
\begin{definition}[$q$-query acceptance probability]
  \label{def:qaccept-prob}
  \uses{def:qforkable-adversary}
  \lean{CatCrypt.Crypto.GeneralForkingLemma.qAcceptProb}
  \leanok
  $\mathrm{acc}(A,x)$ for a $q$-query adversary is the probability that, over a
  commitment and a uniform response vector $\mathrm{Fin}\,q \to R$, the predicate
  accepts the produced $(\text{index}, \text{output})$ pair.
\end{definition}

n42697.content:
\begin{definition}[Guess reduction to a single query]
  \label{def:guess-reduction}
  \uses{def:qforkable-adversary, def:forkable-adversary}
  \lean{CatCrypt.Crypto.GeneralForkingLemma.guessReduction}
  \leanok
  For a guess $I : \mathrm{Fin}\,q$, the \emph{guess reduction} builds a
  single-query forkable adversary: its commit phase absorbs the commitment and a
  full uniform response vector, and its response phase overwrites position $I$
  with the single oracle challenge via $\mathsf{Function.update}$ before running
  $\mathsf{respond}$.
\end{definition}

n42698.content:
\begin{definition}[Acceptance at a guess]
  \label{def:accept-at-guess}
  \lean{CatCrypt.Crypto.GeneralForkingLemma.acceptAtGuess}
  \leanok
  The predicate $\mathsf{acceptAtGuess}(\mathsf{accept}, I)$ accepts a pair
  $(j, y)$ exactly when $j = I$ and $\mathsf{accept}(j,y)$ holds; it restricts
  attention to transcripts whose fork index matches the guess.
\end{definition}

n42699.content:
\begin{lemma}[Guesses partition acceptance]
  \label{lem:sum-accept-at-guess}
  \uses{def:accept-at-guess, def:guess-reduction, def:qaccept-prob}
  \lean{CatCrypt.Crypto.GeneralForkingLemma.sum_acceptAtGuess_eq}
  \leanok
  Summing the reduced acceptance probabilities over all guesses recovers the
  $q$-query acceptance probability:
  \[
    \sum_{I : \mathrm{Fin}\,q}
      \mathrm{acc}\big(\mathsf{guessReduction}(A,I),\, x,\, \mathsf{acceptAtGuess}(\mathsf{accept},I)\big)
    \;=\; \mathrm{acc}(A,x).
  \]
\end{lemma}

n42700.content:
\begin{theorem}[Bellare--Neven aggregation]
  \label{thm:bellare-neven-agg}
  \uses{lem:ennreal-amgm}
  \lean{CatCrypt.Crypto.GeneralForkingLemma.bellare_neven_aggregation}
  \leanok
  Let $q > 0$ and $a, f : \mathrm{Fin}\,q \to \overline{\mathbb{R}}_{\geq 0}$ with
  $f_j \geq a_j^2 - a_j / N$ for every $j$. Then, by Cauchy--Schwarz on the
  per-index bounds,
  \[
    \sum_{j} f_j \;\geq\;
    \frac{\big(\sum_j a_j\big)^2}{q} \;-\; \frac{\sum_j a_j}{N}.
  \]
\end{theorem}

n42701.content:
\begin{definition}[Indexed $q$-fork success probability]
  \label{def:qfork-succ-prob}
  \uses{def:guess-reduction, def:accept-at-guess, def:fork-succ-prob}
  \lean{CatCrypt.Crypto.GeneralForkingLemma.qForkSuccProb}
  \leanok
  The \emph{indexed $q$-fork success probability} sums the single-query fork
  success of every guess reduction, each measured against its guess-restricted
  predicate:
  \[
    \mathrm{qfrk}(A,x) \;=\;
    \sum_{I : \mathrm{Fin}\,q}
      \mathrm{frk}\big(\mathsf{guessReduction}(A,I),\, x,\, \mathsf{acceptAtGuess}(\mathsf{accept},I)\big).
  \]
\end{definition}

n42702.content:
\begin{theorem}[General forking lemma, Bellare--Neven 2006]
  \label{thm:qfork-success-ge}
  \uses{thm:fork-success-ge, thm:bellare-neven-agg, lem:sum-accept-at-guess, def:qfork-succ-prob, def:qaccept-prob}
  \lean{CatCrypt.Crypto.GeneralForkingLemma.qFork_success_ge}
  \leanok
  For every $q$-query forkable adversary $A$ with $q > 0$,
  \[
    \mathrm{qfrk}(A,x) \;\geq\;
    \frac{\mathrm{acc}(A,x)^2}{q} \;-\; \frac{\mathrm{acc}(A,x)}{\lvert R\rvert}.
  \]
  Combining the single-query bound applied to each guess reduction, the guess
  partition of acceptance, and the Cauchy--Schwarz aggregation yields the
  Bellare--Neven bound.
\end{theorem}

n42704.content:
\begin{lemma}[Pairing bilinearity on exponents]
  \label{def:pairing-bilinear}
  \uses{def:pairing-group}
  \lean{CatCrypt.Crypto.PairingGroup.e_bilinear}
  \leanok
  For integer exponents $a, b$,
  $e(g_1^{\,a},\, g_2^{\,b}) = e(g_1, g_2)^{\,a b}$. This is the identity that
  makes pairing-based verification equations checkable from public group
  elements.
\end{lemma}

n42705.content:
\begin{definition}[KZG structured reference string]
  \label{def:kzg-srs}
  \uses{def:pairing-group}
  \lean{CatCrypt.Crypto.PairingGroup.srs₁}
  \leanok
  For a secret $\alpha \in \mathbb{Z}_p$ and degree bound $t$, the KZG
  structured reference string in $G_1$ is the tuple
  $\mathrm{srs}_1(\alpha, t) = (g_1, g_1^{\alpha}, g_1^{\alpha^2}, \dots,
  g_1^{\alpha^t})$; the companion $\mathrm{srs}_2(\alpha) = (g_2, g_2^{\alpha})$
  in $G_2$ supplies the verification key.
\end{definition}

n42706.content:
\begin{definition}[Discrete logarithm advantage]
  \label{def:dl}
  \uses{def:pairing-group, def:advantage}
  \lean{CatCrypt.Crypto.Assumptions.DL_Advantage}
  \leanok
  In the DL game the challenger samples $x \in \mathbb{Z}_p$, hands the
  adversary $h = g_1^{\,x}$, and the adversary wins if it returns $x$. The
  \emph{DL advantage} of $A$ is $\operatorname{Pr}[\text{$A$ outputs }x]$. The DL assumption
  states this is negligible: no efficient adversary recovers exponents.
\end{definition}

n42707.content:
\begin{definition}[Diffie--Hellman group]
  \label{def:ddh-def}
  \lean{CatCrypt.Crypto.Assumptions.DDHDef}
  \leanok
  Abstractly, a Diffie--Hellman group is a scalar-multiplication operation
  $\mathrm{ecdh} : W \to W \to W$ together with a (heap-independent) key
  generator producing pairs $(\text{private}, \text{public})$. This models
  $g \mapsto g^a$ and key sampling without committing to a concrete group.
\end{definition}

n42708.content:
\begin{definition}[Decisional Diffie--Hellman advantage]
  \label{def:ddh}
  \uses{def:ddh-def, def:advantage}
  \lean{CatCrypt.Crypto.Assumptions.DDH_Advantage}
  \leanok
  The DDH advantage is the distinguishing distance between the real game, which
  gives the adversary $(g^a, g^b, g^{ab})$, and the ideal game, which gives
  $(g^a, g^b, c)$ for a fresh uniform $c$. The DDH assumption states this
  advantage is negligible: the true shared secret is indistinguishable from a
  random group element.
\end{definition}

n42709.content:
\begin{definition}[Computational Diffie--Hellman advantage]
  \label{def:cdh}
  \uses{def:ddh-def}
  \lean{CatCrypt.Crypto.Assumptions.CDH_Advantage}
  \leanok
  In the CDH game the adversary receives $(g^a, g^b)$ and wins by outputting the
  shared secret $g^{ab}$. The CDH advantage is $\operatorname{Pr}[\text{$A$ outputs }g^{ab}]$;
  the CDH assumption states it is negligible. CDH is the computational analogue
  of DDH: distinguishing (DDH) implies computing (CDH), but not conversely.
\end{definition}

n42710.content:
\begin{definition}[co-CDH advantage]
  \label{def:cocdh}
  \uses{def:pairing-group}
  \lean{CatCrypt.Crypto.Assumptions.CoCDH_Advantage}
  \leanok
  In a Type~III pairing group the co-CDH game samples $a, b \in \mathbb{Z}_p$,
  gives the adversary $(g_1^{\,a}, g_2^{\,b})$ across the two source groups, and
  the adversary wins by outputting $g_1^{\,ab}$. The co-CDH advantage is this
  winning probability. It is the hardness assumption underlying BLS signatures.
\end{definition}

n42711.content:
\begin{definition}[Gap Diffie--Hellman advantage]
  \label{def:gapdh}
  \uses{def:ddh-def, def:advantage}
  \lean{CatCrypt.Crypto.Assumptions.GapDH_Advantage}
  \leanok
  GapDH strengthens CDH by granting the adversary a DDH decision oracle: it must
  still \emph{compute} $g^{ab}$ from $(g^a, g^b)$, even though it can \emph{check}
  candidate triples. The advantage is the distinguishing distance between the DH
  output and a fresh random value; the assumption states it is negligible. GapDH
  is the standard assumption for X25519-based protocols (WireGuard, Noise), and
  any DDH group is a fortiori a GapDH group.
\end{definition}

n42712.content:
\begin{definition}[$t$-Strong Diffie--Hellman advantage]
  \label{def:tsdh}
  \uses{def:kzg-srs}
  \lean{CatCrypt.Crypto.Assumptions.tSDH_Advantage}
  \leanok
  In the $t$-SDH game the challenger samples $\alpha$ and publishes the SRS
  $(g_1, g_1^{\alpha}, \dots, g_1^{\alpha^t})$. The adversary wins by producing a
  pair $(c, h)$ with $h = g_1^{\,1/(\alpha + c)}$, checked via the pairing
  equation $e(h, g_2^{\,\alpha + c}) = e(g_1, g_2)$. The $t$-SDH advantage is
  this winning probability; it is the core hardness assumption for KZG
  polynomial commitments.
\end{definition}

n42713.content:
\begin{definition}[$q$-SDH group]
  \label{def:qsdh-group}
  \lean{CatCrypt.Crypto.Assumptions.qSDH_Group}
  \leanok
  An abstract cyclic group of prime order carrying scalar arithmetic
  (addition, multiplication, inverse) and scalar multiplication $g \mapsto g^a$,
  finite and with decidable equality. This is the algebraic setting for $q$-SDH,
  abstracting the $G_1$ component of a pairing group without the pairing itself.
\end{definition}

n42714.content:
\begin{definition}[$q$-Strong Diffie--Hellman advantage]
  \label{def:qsdh}
  \uses{def:qsdh-group}
  \lean{CatCrypt.Crypto.Assumptions.qSDH_Advantage}
  \leanok
  The challenger samples a secret $x$ and hands the adversary the challenge
  $(g, g^x, g^{x^2}, \dots, g^{x^q})$; the adversary wins with a pair $(c, h)$
  satisfying $h^{\,x + c} = g$, i.e.\ $h = g^{\,1/(x+c)}$. The $q$-SDH advantage
  is this winning probability. It underlies BBS/BBS+ signatures and anonymous
  credentials, capturing the same hardness as $t$-SDH in a pairing-free setting.
\end{definition}

n42715.content:
\begin{definition}[Oracle Diffie--Hellman advantage]
  \label{def:odh}
  \uses{def:ddh-def, def:advantage}
  \lean{CatCrypt.Crypto.Assumptions.ODH_Advantage}
  \leanok
  ODH augments a DH group with a keyed hash $H$ whose key is the DH secret. The
  advantage is the distinguishing distance between the real game, which returns
  $H(g^{ab}, \ell)$ for a sampled label $\ell$, and the ideal game, which returns
  a fresh random value. The ODH assumption states this is negligible; taking $H$
  to be the identity recovers DDH.
\end{definition}

n42716.content:
\begin{lemma}[DDH and PRF imply ODH]
  \label{def:odh-reduction}
  \uses{def:odh, def:ddh, def:prf}
  \lean{CatCrypt.Crypto.Assumptions.odh_of_ddh_prf}
  \leanok
  If the DH secret can be replaced by a random key at cost $\varepsilon_{ddh}$
  (a DDH step) and the hash keyed by a random value is a PRF at cost
  $\varepsilon_{prf}$, then the ODH advantage is bounded by
  $\varepsilon_{ddh} + \varepsilon_{prf}$, via a two-hop hybrid through the
  triangle inequality.
\end{lemma}

n42717.content:
\begin{definition}[Collision-resistance advantage]
  \label{def:cr-search}
  \uses{def:advantage}
  \lean{CatCrypt.Crypto.Assumptions.CR_Search_Advantage}
  \leanok
  For a hash $h$, the search-CR game has the adversary output a pair
  $(x_1, x_2)$ and wins when $h(x_1) = h(x_2)$ with $x_1 \neq x_2$. The CR
  advantage is this winning probability; collision resistance states it is
  negligible.
\end{definition}

n42718.content:
\begin{definition}[Target collision resistance advantage]
  \label{def:tcr}
  \uses{def:advantage}
  \lean{CatCrypt.Crypto.Assumptions.TCR_Advantage}
  \leanok
  In the TCR (second-preimage) game the adversary receives a random target $x$
  together with $h(x)$ and must find $x' \neq x$ with $h(x') = h(x)$. The TCR
  advantage is this winning probability. TCR is weaker than CR: collision
  resistance implies target collision resistance.
\end{definition}

n42719.content:
\begin{definition}[Preimage-resistance advantage]
  \label{def:pre}
  \uses{def:advantage}
  \lean{CatCrypt.Crypto.Assumptions.Pre_Advantage}
  \leanok
  In the preimage game the adversary receives $y = h(x)$ for a random $x$ and
  wins by outputting any $x'$ with $h(x') = y$. The Pre advantage is this
  probability. For compressing hashes it is implied by collision resistance.
\end{definition}

n42720.content:
\begin{definition}[One-wayness advantage]
  \label{def:owf}
  \uses{def:advantage}
  \lean{CatCrypt.Crypto.Assumptions.OWF_Advantage}
  \leanok
  For a function $f$, the inversion game samples $x$, hands the adversary
  $f(x)$, and it wins by returning any preimage $x'$ with $f(x') = f(x)$. The
  OWF advantage is this winning probability; one-wayness states it is negligible.
\end{definition}

n42721.content:
\begin{definition}[One-way permutation]
  \label{def:owp}
  \uses{def:owf}
  \lean{CatCrypt.Crypto.Assumptions.OWPDef}
  \leanok
  A one-way permutation is a one-way function that is additionally a bijection.
  RSA is the canonical conjectured instance.
\end{definition}

n42722.content:
\begin{definition}[Pseudorandom-generator advantage]
  \label{def:prg}
  \uses{def:advantage}
  \lean{CatCrypt.Crypto.Assumptions.PRG_Advantage}
  \leanok
  For a stretch function $G$, the PRG advantage is the distinguishing distance
  between $G(\text{seed})$ for a random seed and a uniformly random output. The
  PRG assumption states this is negligible; a secure PRG is in particular a
  one-way function.
\end{definition}

n42723.content:
\begin{definition}[RSA inversion advantage]
  \label{def:rsa}
  \uses{def:advantage}
  \lean{CatCrypt.Crypto.Assumptions.RSA_Advantage}
  \leanok
  The RSA game samples a key pair and a random preimage $x$, sets
  $y = \mathrm{rsa}(pk, x)$, and asks the adversary for $x'$ with
  $\mathrm{rsa}(pk, x') = y$. The RSA advantage is the distinguishing distance
  between this real game and the always-reject ideal game; the RSA assumption
  states it is negligible.
\end{definition}

n42724.content:
\begin{definition}[Pseudorandom-permutation advantage]
  \label{def:prp}
  \uses{def:advantage}
  \lean{CatCrypt.Crypto.Assumptions.PRP_Advantage}
  \leanok
  For a block cipher $E$, the PRP advantage is the distinguishing distance
  between the keyed permutation $E(k, \cdot)$ (random key) and a random
  \emph{function}. Together with the switching bound below this yields the full
  PRP security bound.
\end{definition}

n42725.content:
\begin{definition}[Strong-PRP advantage]
  \label{def:sprp}
  \uses{def:advantage}
  \lean{CatCrypt.Crypto.Assumptions.SPRP_Advantage}
  \leanok
  The strong-PRP game grants the adversary both the forward oracle $E(k, \cdot)$
  and the inverse oracle $D(k, \cdot)$; the SPRP advantage is the distinguishing
  distance from a pair of independent random functions. This is the notion
  needed by modes that decrypt (e.g.\ CBC).
\end{definition}

n42726.content:
\begin{definition}[Pseudorandom-function advantage]
  \label{def:prf}
  \uses{def:advantage}
  \lean{CatCrypt.Crypto.Assumptions.PRF_Advantage}
  \leanok
  For a keyed function $F$, the (single-query) PRF advantage is the
  distinguishing distance between $F(k, x)$ for a random key and a uniformly
  random output. The PRF assumption states this is negligible.
\end{definition}

n42727.content:
\begin{definition}[PRP/PRF switching bound]
  \label{def:prp-prf-switch}
  \lean{CatCrypt.Crypto.Assumptions.PRP_PRF_SwitchingBound}
  \leanok
  The birthday term $q(q-1)/(2|W|)$ bounding the statistical gap between a random
  permutation and a random function over $q$ queries on a domain of size $|W|$.
  It is the additive correction relating the PRP advantage (which uses a random
  function as ideal) to true permutation security.
\end{definition}

n42728.content:
\begin{definition}[MAC forgery advantage]
  \label{def:mac}
  \uses{def:advantage}
  \lean{CatCrypt.Crypto.Assumptions.MAC_Advantage}
  \leanok
  In the (indistinguishability form of) MAC game a random key is sampled and the
  adversary receives the tag on its chosen message; the MAC advantage is the
  distinguishing distance between this real tag and a uniformly random tag. The
  unforgeability assumption states it is negligible --- equivalent to
  single-query strong unforgeability up to a $1/|W|$ term.
\end{definition}

n42729.content:
\begin{definition}[AEAD confidentiality advantage]
  \label{def:aead}
  \uses{def:advantage}
  \lean{CatCrypt.Crypto.Assumptions.AEAD_Advantage}
  \leanok
  For an authenticated-encryption scheme the (IND-CPA form) AEAD advantage is the
  distinguishing distance between the real game, which returns
  $\mathrm{encrypt}(k, \mathit{pt}, \mathit{ad})$ under a random key, and the
  ideal game, which returns a uniformly random ciphertext. Security states this
  is negligible.
\end{definition}

n42730.content:
\begin{definition}[AEAD IND-CCA2 advantage]
  \label{def:aead-cca}
  \uses{def:aead}
  \lean{CatCrypt.Crypto.Assumptions.AEAD_CCA_Advantage}
  \leanok
  The IND-CCA2 game equips the adversary with both an encryption oracle and a
  decryption oracle; the advantage is the distinguishing distance between real
  encryption-plus-decryption and (random encryption, reject-all decryption). This
  combines confidentiality and ciphertext integrity, and implies the IND-CPA
  notion above.
\end{definition}

n42732.content:
\begin{definition}[Projective $x$-only differential addition]
  \label{def:xdadd}
  \lean{CatCrypt.Crypto.ECC.xdadd}
  \leanok
  Given projective $x$-coordinates of $P$, $Q$ and their difference
  $P-Q$ (Costello--Smith eq.~13),
  \begin{align*}
    \mathrm{DA} &= (X_P - Z_P)(X_Q + Z_Q), &
    \mathrm{CB} &= (X_P + Z_P)(X_Q - Z_Q), \\
    \mathsf{xdadd}\,(X_P,Z_P)\,(X_Q,Z_Q)\,(X_D,Z_D)
      &= \bigl(\,Z_D\,(\mathrm{DA}+\mathrm{CB})^2,\;\;
                  X_D\,(\mathrm{DA}-\mathrm{CB})^2\,\bigr).
  \end{align*}
  Its output represents $x(P+Q)$.
\end{definition}

n42733.content:
\begin{lemma}[Symmetry of $\mathsf{xdadd}$]
  \label{lem:xdadd-symm}
  \uses{def:xdadd}
  \lean{CatCrypt.Crypto.ECC.xdadd_symm}
  \leanok
  $\mathsf{xdadd}\,PZ\,QZ\,DZ = \mathsf{xdadd}\,QZ\,PZ\,DZ$: the difference
  term $\mathrm{DA}-\mathrm{CB}$ is squared, so swapping the two summands
  leaves the result unchanged.
\end{lemma}

n42734.content:
\begin{definition}[Montgomery curve parameters]
  \label{def:monty-params}
  \lean{CatCrypt.Crypto.ECC.MontyParams}
  \leanok
  A parameter record over a commutative ring $F$ carrying the curve
  coefficient $A$ (for $y^2 = x^3 + A x^2 + x$) and the derived constant
  $a_{24}$, kept as an independent field subject to the well-formedness
  invariant $4\,a_{24} = A + 2$ (avoiding division in the representation).
\end{definition}

n42735.content:
\begin{definition}[Curve25519 parameters]
  \label{def:curve25519-params}
  \uses{def:monty-params}
  \lean{CatCrypt.Crypto.ECC.curve25519Params}
  \leanok
  The Montgomery parameters of Curve25519: $A = 486662$ and
  $a_{24} = 121666 = (486662 + 2)/4$.
\end{definition}

n42736.content:
\begin{definition}[Projective equivalence]
  \label{def:proj-equiv}
  \lean{CatCrypt.Crypto.ECC.ProjEquiv}
  \leanok
  Two pairs are $x$-equivalent, written $(X_1,Z_1) \sim (X_2,Z_2)$, iff
  $X_1 Z_2 = X_2 Z_1$; i.e.\ they carry the same $x$-coordinate
  $X/Z$ in the field of fractions. The relation is reflexive and
  symmetric.
\end{definition}

n42737.content:
\begin{lemma}[Restricted transitivity of $\sim$]
  \label{lem:proj-equiv-trans}
  \uses{def:proj-equiv}
  \lean{CatCrypt.Crypto.ECC.ProjEquiv.trans}
  \leanok
  Over a field, if $p \sim q$, $q \sim r$, and $q$ is nondegenerate
  ($q.1 \neq 0$ or $q.2 \neq 0$), then $p \sim r$. Transitivity can fail
  when the middle term is $(0,0)$, so nondegeneracy is required.
\end{lemma}

n42738.content:
\begin{theorem}[$\mathsf{xdbl}$ respects $\sim$]
  \label{thm:xdbl-projequiv}
  \uses{def:xdbl, def:proj-equiv}
  \lean{CatCrypt.Crypto.ECC.xdbl_projEquiv}
  \leanok
  If $p \sim q$ then $\mathsf{xdbl}\,a_{24}\,p \sim \mathsf{xdbl}\,a_{24}\,q$.
  Both coordinates of $\mathsf{xdbl}$ are homogeneous of degree $4$ in
  $(X,Z)$, so a common scaling of the input scales the output uniformly.
\end{theorem}

n42739.content:
\begin{theorem}[$\mathsf{xdadd}$ respects $\sim$]
  \label{thm:xdadd-projequiv}
  \uses{def:xdadd, def:proj-equiv}
  \lean{CatCrypt.Crypto.ECC.xdadd_projEquiv}
  \leanok
  If $p \sim p'$, $q \sim q'$, and $d \sim d'$ then
  $\mathsf{xdadd}\,p\,q\,d \sim \mathsf{xdadd}\,p'\,q'\,d'$: each of
  $\mathrm{DA}+\mathrm{CB} = 2(X_P X_Q - Z_P Z_Q)$ and
  $\mathrm{DA}-\mathrm{CB} = 2(X_P Z_Q - X_Q Z_P)$ is homogeneous in each
  argument, and the $X_D/Z_D$ factors cancel.
\end{theorem}

n42740.content:
\begin{definition}[$\mathsf{MontyCurveGroup}$]
  \label{def:monty-curve-group}
  \uses{def:xdbl, def:xdadd, def:monty-params}
  \lean{CatCrypt.Crypto.ECC.MontyCurveGroup}
  \leanok
  A hypothesis class packaging the Costello--Smith~\S4 correspondence: an
  abelian group $G$ of curve points, an $x$-coordinate projection
  $\mathsf{xProj} : G \to F \times F$, and the two specifications
  \begin{align*}
    \text{(doubling)}\quad&\mathsf{xdbl}\,a_{24}\,(\mathsf{xProj}\,P)
      \;\sim\; \mathsf{xProj}\,(P+P), \\
    \text{(addition)}\quad&\mathsf{xdadd}\,(\mathsf{xProj}\,P)\,
      (\mathsf{xProj}\,Q)\,(\mathsf{xProj}\,(P-Q))
      \;\sim\; \mathsf{xProj}\,(P+Q),
  \end{align*}
  stated up to projective equivalence.
\end{definition}

n42741.content:
\begin{definition}[Bits to natural]
  \label{def:bits-to-nat}
  \lean{CatCrypt.Crypto.ECC.bitsToNat}
  \leanok
  The natural number read from a bit list, MSB first:
  $\mathsf{bitsToNat}(b::bs) = 2\,\mathsf{bitsToNat}(bs) + [b]$ and
  $\mathsf{bitsToNat}\,[] = 0$.
\end{definition}

n42742.content:
\begin{definition}[Ladder step]
  \label{def:ladder-step}
  \lean{CatCrypt.Crypto.ECC.ladderStep}
  \leanok
  One double-and-add step on a state $(R_0, R_1)$ of an abelian group,
  branching on bit $b$:
  \[
    \mathsf{ladderStep}\,(R_0,R_1)\,b =
      \begin{cases}
        (R_0 + R_1,\; R_1 + R_1) & b = \mathsf{true},\\
        (R_0 + R_0,\; R_0 + R_1) & b = \mathsf{false}.
      \end{cases}
  \]
\end{definition}

n42743.content:
\begin{definition}[Ladder fold]
  \label{def:ladder-fold}
  \uses{def:ladder-step}
  \lean{CatCrypt.Crypto.ECC.ladderFold}
  \leanok
  Iterating $\mathsf{ladderStep}$ over a bit list (head processed first,
  MSB first) from the initial state $(0, P)$.
\end{definition}

n42744.content:
\begin{definition}[Ladder invariant]
  \label{def:ladder-inv}
  \lean{CatCrypt.Crypto.ECC.LadderInv}
  \leanok
  The predicate $\mathsf{LadderInv}\,P\,a\,(R_0,R_1)$ asserting
  $R_0 = a \cdot P$ and $R_1 = (a+1)\cdot P$.
\end{definition}

n42745.content:
\begin{theorem}[Montgomery ladder correctness (algebraic)]
  \label{thm:ladder-fold-correct}
  \uses{def:ladder-fold, def:ladder-inv, def:bits-to-nat}
  \lean{CatCrypt.Crypto.ECC.ladderFold_correct}
  \leanok
  For any abelian group $G$, any $P : G$ and any bit list $bits$,
  \[
    \mathsf{LadderInv}\,P\,(\mathsf{bitsToNat}\,bits)\,
      (\mathsf{ladderFold}\,P\,bits),
  \]
  i.e.\ the fold ends in state $(n\cdot P, (n+1)\cdot P)$ with
  $n = \mathsf{bitsToNat}\,bits$. Proved by induction on bit length.
\end{theorem}

n42746.content:
\begin{definition}[Field-level ladder step]
  \label{def:xladder-step}
  \uses{def:xdbl, def:xdadd}
  \lean{CatCrypt.Crypto.ECC.xladderStep}
  \leanok
  One step of the $x$-only ladder on projective state
  $(R_0, R_1) \in (F\times F)^2$, carrying the base $x$-coordinate $x_P$
  as the invariant difference:
  \[
    \mathsf{xladderStep}\,a_{24}\,x_P\,(R_0,R_1)\,b =
      \begin{cases}
        (\mathsf{xdadd}\,R_0\,R_1\,x_P,\; \mathsf{xdbl}\,a_{24}\,R_1) & b,\\
        (\mathsf{xdbl}\,a_{24}\,R_0,\; \mathsf{xdadd}\,R_0\,R_1\,x_P) & \neg b.
      \end{cases}
  \]
  This is the pure field program a Jasmin/bedrock2/Rust implementation runs.
\end{definition}

n42747.content:
\begin{definition}[Field-level ladder fold]
  \label{def:xladder-fold}
  \uses{def:xladder-step}
  \lean{CatCrypt.Crypto.ECC.xladderFold}
  \leanok
  Iterating $\mathsf{xladderStep}$ over a bit list from the initial
  projective state $((1,0),\,x_P)$, where $(1,0)$ represents the point at
  infinity.
\end{definition}

n42748.content:
\begin{definition}[Field-level ladder invariant]
  \label{def:xladder-inv}
  \uses{def:proj-equiv, def:monty-curve-group}
  \lean{CatCrypt.Crypto.ECC.XLadderInv}
  \leanok
  The projective invariant tying the field state to the abstract group:
  $\mathsf{XLadderInv}\,P\,n\,(s_0,s_1)$ holds iff
  $s_0 \sim \mathsf{xProj}\,(n\cdot P)$ and
  $s_1 \sim \mathsf{xProj}\,((n+1)\cdot P)$.
\end{definition}

n42749.content:
\begin{theorem}[Field-level step preserves the invariant]
  \label{thm:xladder-step-preserves}
  \uses{def:xladder-step, def:xladder-inv, thm:xdbl-projequiv, thm:xdadd-projequiv, lem:proj-equiv-trans, def:monty-curve-group}
  \lean{CatCrypt.Crypto.ECC.xladderStep_preserves_invariant}
  \leanok
  Over a field, given negation-invariance of $\mathsf{xProj}$ and
  nondegeneracy of the intermediate $\mathsf{xdbl}$/$\mathsf{xdadd}$
  outputs, if $\mathsf{XLadderInv}\,P\,n\,s$ holds then so does
  $\mathsf{XLadderInv}\,P\,(2n + [b])\,(\mathsf{xladderStep}\,a_{24}\,
  (\mathsf{xProj}\,P)\,s\,b)$. Composes
  \ref{thm:xdbl-projequiv}, \ref{thm:xdadd-projequiv} and
  \ref{lem:proj-equiv-trans} with the group specs.
\end{theorem}

n42750.content:
\begin{definition}[Montgomery curve as Weierstrass curve]
  \label{def:montgomeryW}
  \lean{CatCrypt.Crypto.ECC.montgomeryW}
  \leanok
  The equation $y^2 = x^3 + A x^2 + x$ is literally the Weierstrass curve
  with $(a_1,a_2,a_3,a_4,a_6) = (0, A, 0, 1, 0)$. Instantiating Mathlib's
  \texttt{WeierstrassCurve} at these coefficients reuses its proved
  \texttt{AddCommGroup} structure on affine points.
\end{definition}

n42751.content:
\begin{lemma}[Weierstrass equation is the Montgomery equation]
  \label{lem:montgomeryW-equation}
  \uses{def:montgomeryW}
  \lean{CatCrypt.Crypto.ECC.montgomeryW_equation}
  \leanok
  A point $(x,y)$ lies on $\mathsf{montgomeryW}\,A$ iff
  $y^2 = x^3 + A x^2 + x$.
\end{lemma}

n42752.content:
\begin{definition}[Projective $x$-coordinate map]
  \label{def:xprojW}
  \uses{def:montgomeryW}
  \lean{CatCrypt.Crypto.ECC.xProjW}
  \leanok
  The map sending a Weierstrass affine point to its projective
  $x$-coordinate: the point at infinity $\mapsto (1,0)$, and a finite
  point $(x,y) \mapsto (x,1)$. It is negation-invariant, since Montgomery
  negation flips only $y$.
\end{definition}

n42755.content:
\begin{definition}[Weierstrass transport into $\mathsf{MontyCurveGroup}$]
  \label{def:montgomeryW-mcg}
  \uses{def:monty-curve-group, def:montgomeryW, def:xprojW, thm:xdbl-spec-w, thm:xdadd-spec-w}
  \lean{CatCrypt.Crypto.ECC.montgomeryW_MontyCurveGroup}
  \leanok
  Packaging: the Weierstrass group on $(\mathsf{montgomeryW}\,A)$'s affine
  points, with $x$-map $\mathsf{xProjW}\,A$, is a
  $\mathsf{MontyCurveGroup}$ instance whenever $2 \neq 0$ and
  $4\,a_{24} = A + 2$. This discharges the Costello--Smith~\S4
  correspondence with no separate Montgomery-form group-law port.
\end{definition}

n42757.content:
\begin{definition}[Curve25519 base field]
  \label{def:fp25519}
  \uses{def:curve25519-prime}
  \lean{CatCrypt.Crypto.ECC.Fp25519}
  \leanok
  The type alias $\mathbb{F}_p = \mathbb{Z}/p\mathbb{Z}$ for
  $p = 2^{255} - 19$.
\end{definition}

n42758.content:
\begin{definition}[Base-field primality (AUCurves bridge, taken as an axiom)]
  \label{def:curve25519-prime-prime}
  \uses{def:curve25519-prime}
  \lean{CatCrypt.Crypto.ECC.curve25519Prime_prime}
  \leanok
  $\mathsf{Nat.Prime}\,(2^{255} - 19)$. Proving this in Lean needs a costly
  Pocklington/Pratt certificate; it is discharged in the Rocq AUCurves
  development and imported across the Rocq$\leftrightarrow$Lean boundary as
  an axiom. It unlocks $\mathsf{Field}\,\mathbb{F}_p$.
\end{definition}

n42759.content:
\begin{definition}[Concrete Curve25519 point group]
  \label{def:curve25519-point}
  \uses{def:montgomeryW, def:fp25519}
  \lean{CatCrypt.Crypto.ECC.Curve25519Point}
  \leanok
  The affine points of $\mathsf{montgomeryW}\,(486662)$ over
  $\mathbb{F}_p$, an $\mathsf{AddCommGroup}$ inherited from Mathlib.
\end{definition}

n42760.content:
\begin{definition}[Curve25519 $\mathsf{MontyCurveGroup}$ instance]
  \label{def:curve25519-mcg}
  \uses{def:curve25519-point, def:montgomeryW-mcg, def:curve25519-params, def:curve25519-prime-prime}
  \lean{CatCrypt.Crypto.ECC.curve25519_MontyCurveGroup}
  \leanok
  Specialising \ref{def:montgomeryW-mcg} to $A = 486662$,
  $a_{24} = 121666$ over $\mathbb{F}_p$ (using $2 \neq 0$ and
  $4\cdot 121666 = 486662 + 2$): the $x$-only formulas correctly compute
  scalar multiplication on $\mathsf{Curve25519Point}$.
\end{definition}

n42761.content:
\begin{definition}[X25519 scalar multiplication]
  \label{def:x25519}
  \lean{CatCrypt.Crypto.ECC.x25519}
  \leanok
  $\mathsf{x25519}\,k\,P = k \cdot P$ in the group. For the Curve25519
  base point this is X25519 scalar multiplication.
\end{definition}

n42762.content:
\begin{theorem}[Ladder computes X25519]
  \label{thm:x25519-eq-ladder}
  \uses{def:x25519, def:ladder-fold, thm:ladder-fold-correct}
  \lean{CatCrypt.Crypto.ECC.x25519_eq_ladder}
  \leanok
  $\mathsf{x25519}\,(\mathsf{bitsToNat}\,bits)\,P
     = (\mathsf{ladderFold}\,P\,bits).1$, a corollary of
  \ref{thm:ladder-fold-correct}.
\end{theorem}

n42763.content:
\begin{definition}[Curve25519 subgroup order]
  \label{def:curve25519-suborder}
  \lean{CatCrypt.Crypto.ECC.curve25519SubgroupOrder}
  \leanok
  $\ell = 2^{252} + 27742317777372353535851937790883648493$, the order of
  Curve25519's prime-order subgroup and of the RFC~7748 base point.
\end{definition}

n42764.content:
\begin{definition}[Subgroup order primality (AUCurves bridge, taken as an axiom)]
  \label{def:curve25519-suborder-prime}
  \uses{def:curve25519-suborder}
  \lean{CatCrypt.Crypto.ECC.curve25519SubgroupOrder_prime}
  \leanok
  $\mathsf{Nat.Prime}\,\ell$. Bridged from the AUCurves development
  ($E/E[4]$ has prime order $\ell$); imported as an axiom exactly as
  \ref{def:curve25519-prime-prime}. This underpins the cyclic-subgroup
  argument that $n\cdot B \neq 0$ for $0 < n < \ell$.
\end{definition}

n42765.content:
\begin{definition}[Curve25519 base point (AUCurves bridge, taken as an axiom)]
  \label{def:curve25519-basepoint}
  \uses{def:curve25519-point}
  \lean{CatCrypt.Crypto.ECC.curve25519_basepoint}
  \leanok
  A concrete $\mathsf{Curve25519Point}$ standing for the RFC~7748 base
  point $u = 9$. Bridged from AUCurves and taken as an axiom; only its
  additive order is constrained (see \ref{def:curve25519-basepoint-addorder}),
  so downstream results hold for any order-$\ell$ point.
\end{definition}

n42766.content:
\begin{definition}[Base-point order (AUCurves bridge, taken as an axiom)]
  \label{def:curve25519-basepoint-addorder}
  \uses{def:curve25519-basepoint, def:curve25519-suborder}
  \lean{CatCrypt.Crypto.ECC.curve25519_basepoint_addOrder}
  \leanok
  $\mathsf{addOrderOf}\,B = \ell$: the base point has additive order equal
  to the subgroup order ($E\_basepoint\_order$, AUCurves). Bridged and
  taken as an axiom.
\end{definition}

n42767.content:
\begin{definition}[Ladder nondegeneracy]
  \label{def:ladder-nondeg}
  \uses{def:xdbl, def:xdadd, def:curve25519-point, def:curve25519-mcg}
  \lean{CatCrypt.Crypto.ECC.LadderNondeg}
  \leanok
  The predicate asserting that, at every scalar $n \le \mathsf{bitsToNat}\,bits$
  along the ladder path over $P$, the intermediate $\mathsf{xdbl}$ and
  $\mathsf{xdadd}$ outputs are projectively nondegenerate (not $(0,0)$).
  This is the side condition needed to invoke
  \ref{lem:proj-equiv-trans} at each step.
\end{definition}

n42768.content:
\begin{theorem}[Field-level ladder correctness for Curve25519]
  \label{thm:xladder-curve25519-correct}
  \uses{def:xladder-fold, def:xladder-inv, thm:xladder-step-preserves, def:curve25519-mcg, def:ladder-nondeg}
  \lean{CatCrypt.Crypto.ECC.xladderFold_curve25519_correct}
  \leanok
  For a point $P$, a bit list, and $\mathsf{LadderNondeg}\,P\,bits$, the
  field-level fold $\mathsf{xladderFold}$ satisfies $\mathsf{XLadderInv}$
  with the abstract-group ladder. Proved by induction, stepping with
  \ref{thm:xladder-step-preserves}.
\end{theorem}

n42769.content:
\begin{theorem}[End-to-end X25519 correctness, conditional on nondegeneracy]
  \label{thm:x25519-ladder-correct}
  \uses{thm:xladder-curve25519-correct, def:x25519, def:ladder-nondeg}
  \lean{CatCrypt.Crypto.ECC.x25519_ladder_correct}
  \leanok
  Given $\mathsf{LadderNondeg}\,P\,bits$, the first component of the
  field-level ladder run on $\mathsf{xProj}\,P$ is projectively equivalent
  to $\mathsf{xProj}\,(\mathsf{x25519}\,(\mathsf{bitsToNat}\,bits)\,P)$ ---
  correctness wherever the ladder path stays nondegenerate.
\end{theorem}

n42770.content:
\begin{theorem}[Base point discharges nondegeneracy]
  \label{thm:curve25519-basepoint-laddernondeg}
  \uses{def:ladder-nondeg, def:curve25519-basepoint, def:curve25519-basepoint-addorder, def:curve25519-suborder-prime}
  \lean{CatCrypt.Crypto.ECC.curve25519_basepoint_LadderNondeg}
  \leanok
  For any bit list whose value is below the subgroup order $\ell$, the
  entire ladder path over the base point $B$ is projectively nondegenerate:
  $\mathsf{LadderNondeg}\,B\,bits$. Since $\ell$ is an odd prime, no
  non-identity multiple $n\cdot B$ ($0 < n < \ell$) is a $4$-torsion point,
  which is exactly what forces each $\mathsf{xdbl}$/$\mathsf{xdadd}$ output
  to be nondegenerate.
\end{theorem}

n42772.content:
\begin{definition}[One-time pad (over $\mathsf{Bool}$)]
  \label{def:otp-scheme}
  \uses{def:spcomp}
  \lean{CatCrypt.Examples.OTP.BoolOTP}
  \leanok
  The one-time pad $\mathsf{BoolOTP}$ is the encryption scheme on
  $\mathsf{Bool}$ with a uniform key, $\mathsf{enc}(k,m) = k \oplus m$ and
  $\mathsf{dec}(k,c) = k \oplus c$.
\end{definition}

n42774.content:
\begin{lemma}[Challenge games couple]
  \label{lem:otp-coupling}
  \uses{def:otp-scheme}
  \lean{CatCrypt.Examples.OTP.otp_indcpa_coupling}
  \leanok
  For all messages $m_0, m_1$, the two IND-CPA challenge games --- encrypting
  $m_0$ versus $m_1$ under a uniform key --- are related by the identity coupling:
  they differ only by XOR-ing the uniform key with $m_0$ against $m_1$, and
  $k \mapsto k \oplus (m_0 \oplus m_1)$ is a bijection of the uniform key.
\end{lemma}

n42775.content:
\begin{theorem}[Perfect IND-CPA security]
  \label{thm:otp-perfect}
  \uses{lem:otp-coupling}
  \lean{CatCrypt.Examples.OTP.otp_perfect_indcpa}
  \leanok
  The one-time pad has \emph{perfect} IND-CPA security: for all messages
  $m_0, m_1$ and every adversary $A$,
  \[
    \mathsf{Adv}^{\mathrm{IND\text{-}CPA}}_{\mathsf{BoolOTP}}(m_0, m_1, A) \;=\; 0.
  \]
\end{theorem}

n42776.content:
\begin{definition}[Bijection PRF family]
  \label{def:bijprf}
  \uses{def:spcomp}
  \lean{CatCrypt.Examples.PRF.BijPRFFamily, CatCrypt.Examples.PRF.BijPRFFamily.toPRFScheme}
  \leanok
  A bijection PRF family has finite nonempty key, input, and output types together
  with, for each input $x$, a bijection $\mathsf{bij}_x : \mathrm{Key} \simeq
  \mathrm{Output}$. It induces a PRF scheme evaluating $\mathsf{eval}(k, x) =
  \mathsf{bij}_x(k)$.
\end{definition}

n42777.content:
\begin{lemma}[Real and ideal oracles couple]
  \label{lem:bijprf-coupling}
  \uses{def:bijprf}
  \lean{CatCrypt.Examples.PRF.bijPRF_coupling}
  \leanok
  For every input $x$, the real oracle (a uniform key run through
  $\mathsf{bij}_x$) and the ideal oracle (a uniform output) are related by the
  bijection coupling $\mathsf{bij}_x$.
\end{lemma}

n42778.content:
\begin{theorem}[Perfect PRF security]
  \label{thm:bijprf-perfect}
  \uses{lem:bijprf-coupling}
  \lean{CatCrypt.Examples.PRF.bijPRF_perfect}
  \leanok
  A bijection PRF family has perfect security: for every input $x$ and adversary
  $A$, the PRF advantage $\mathsf{Adv}^{\mathrm{PRF}}(x, A) = 0$.
\end{theorem}

n42779.content:
\begin{corollary}[XOR PRF]
  \label{cor:xorprf}
  \uses{thm:bijprf-perfect}
  \lean{CatCrypt.Examples.PRF.boolXorPRF, CatCrypt.Examples.PRF.boolXorPRF_perfect}
  \leanok
  The XOR pseudorandom function $F(k, x) = k \oplus x$, instantiating the family by
  $x \mapsto (k \mapsto k \oplus x)$, has perfect PRF security.
\end{corollary}

n42781.content:
\begin{definition}[Acceptance]
  \label{def:schnorr-accepts}
  A transcript $(a, c, s)$ is accepting for public key $\mathit{pk}$ when
  $g^{s} = a \cdot \mathit{pk}^{c}$.
  \lean{CatCrypt.Examples.Schnorr.schnorrAccepts}
  \leanok
\end{definition}

n42782.content:
\begin{theorem}[Completeness]
  \label{thm:schnorr-complete}
  \uses{def:schnorr-accepts}
  \lean{CatCrypt.Examples.Schnorr.schnorr_honest_accepts}
  \leanok
  The honest prover with witness $w$, commitment $a = g^{r}$, and response
  $s = r + w c$ is always accepted.
\end{theorem}

n42783.content:
\begin{theorem}[Special soundness]
  \label{thm:schnorr-soundness}
  \uses{def:schnorr-accepts}
  \lean{CatCrypt.Examples.Schnorr.schnorr_special_soundness}
  \leanok
  Two accepting transcripts $(a, c_1, s_1)$ and $(a, c_2, s_2)$ with the same
  commitment and $c_1 \neq c_2$ determine the discrete-log witness:
  \[
    \mathit{pk} \;=\; g^{\,(s_1 - s_2)(c_1 - c_2)^{-1}}.
  \]
\end{theorem}

n42784.content:
\begin{theorem}[Forking bound]
  \label{thm:schnorr-forking}
  \uses{thm:schnorr-soundness}
  \lean{CatCrypt.Examples.Schnorr.schnorr_forking_bound}
  \leanok
  Instantiating the general forking lemma at a Schnorr forger $A$ bounds the
  probability of a successful fork below by
  $\mathrm{acc}(A)^2 - \mathrm{acc}(A)/p$, where $\mathrm{acc}(A)$ is $A$'s
  acceptance probability.
\end{theorem}

n42785.content:
\begin{theorem}[Discrete log from forking]
  \label{thm:schnorr-dl}
  \uses{thm:schnorr-soundness, thm:schnorr-forking}
  \lean{CatCrypt.Examples.Schnorr.dlFromForking, CatCrypt.Examples.Schnorr.dlFromForking_correct}
  \leanok
  Forking a Schnorr forger and applying special-soundness extraction yields a
  discrete-log solver: on a successful fork the extracted scalar is the true
  discrete logarithm of the public key, $g^{(s_1 - s_2)(c_1 - c_2)^{-1}} =
  \mathit{pk}$.
\end{theorem}

n42786.content:
\begin{definition}[Bijection generator]
  \label{def:bijprg}
  \uses{def:spcomp}
  \lean{CatCrypt.Examples.PRG.PRGScheme, CatCrypt.Examples.PRG.BijPRG, CatCrypt.Examples.PRG.BijPRG.toPRGScheme}
  \leanok
  A PRG scheme has a stretch map $\mathrm{Seed} \to \mathrm{Output}$; a bijection
  generator is one whose stretch map is a bijection $\mathrm{Seed} \simeq
  \mathrm{Output}$.
\end{definition}

n42787.content:
\begin{lemma}[Real and ideal generators couple]
  \label{lem:bijprg-coupling}
  \uses{def:bijprg}
  \lean{CatCrypt.Examples.PRG.bijPRG_coupling}
  \leanok
  Stretching a uniform seed through a bijection and sampling a uniform output are
  related by the bijection coupling.
\end{lemma}

n42788.content:
\begin{theorem}[Perfect PRG security]
  \label{thm:bijprg-perfect}
  \uses{lem:bijprg-coupling}
  \lean{CatCrypt.Examples.PRG.bijPRG_perfect, CatCrypt.Examples.PRG.boolXorPRG_perfect}
  \leanok
  A bijection generator has perfect security: for every adversary $A$, the PRG
  advantage is $0$. The XOR generator is a concrete instance.
\end{theorem}

n42790.content:
\begin{definition}[Encrypt-then-MAC combinator]
  \label{def:etm}
  \uses{def:otp-scheme}
  \lean{CatCrypt.Examples.EncryptThenMAC.EtM}
  \leanok
  Given an encryption scheme $E$ and a MAC $\mathsf{mac}$, the combinator encrypts
  with $E$ and appends the tag: $\mathsf{enc}((k_e, k_m), m) = (c,
  \mathsf{mac}(k_m, c))$ where $c \leftarrow E.\mathsf{enc}(k_e, m)$; decryption
  checks the tag before decrypting.
\end{definition}

n42791.content:
\begin{theorem}[Correctness is preserved]
  \label{thm:etm-correct}
  \uses{def:etm}
  \lean{CatCrypt.Examples.EncryptThenMAC.EtM_correct}
  \leanok
  If the underlying encryption scheme is correct, so is the Encrypt-then-MAC
  combinator built from it, for any MAC.
\end{theorem}

n42792.content:
\begin{theorem}[Perfect IND-CPA of the XOR instantiation]
  \label{thm:etm-perfect}
  \uses{def:etm, thm:otp-perfect}
  \lean{CatCrypt.Examples.EncryptThenMAC.boolEtM_perfect_indcpa}
  \leanok
  The one-time pad composed with the XOR MAC has perfect IND-CPA security:
  advantage exactly $0$ for every adversary.
\end{theorem}

n42793.content:
\begin{definition}[Keyed hash tag]
  \label{def:basichash}
  \uses{def:spcomp}
  \lean{CatCrypt.Examples.BasicHash.HashFunc, CatCrypt.Examples.BasicHash.xorHash}
  \leanok
  A hash function keys a nonce to a tag; the reader accepts when the tag matches.
  The XOR hash is $H(k, n) = k \oplus n$.
\end{definition}

n42794.content:
\begin{theorem}[Perfect authentication]
  \label{thm:basichash-auth}
  \uses{def:basichash}
  \lean{CatCrypt.Examples.BasicHash.auth_perfect_bij, CatCrypt.Examples.BasicHash.auth_zero_advantage_xor}
  \leanok
  For any bijection-family hash, authentication is perfect: the real and ideal
  games couple, so the authentication advantage is $0$ for every nonce and
  adversary. The XOR hash is such a family.
\end{theorem}

n42795.content:
\begin{theorem}[Unlinkability counterexample]
  \label{thm:basichash-unlink}
  \uses{def:basichash}
  \lean{CatCrypt.Examples.BasicHash.xorHash_correlated, CatCrypt.Examples.BasicHash.unlink_real_always_true, CatCrypt.Examples.BasicHash.unlink_ideal_not_always_true}
  \leanok
  The XOR hash leaks a key-independent correlation, $\,(k \oplus n_1) \oplus (k
  \oplus n_2) = n_1 \oplus n_2$. A distinguisher testing this relation accepts the
  shared-key (real) game with certainty, but with independent keys the same test
  can fail --- so the two unlinkability games differ, and unlinkability fails.
\end{theorem}

n42796.content:
\begin{definition}[Hybrid public-key scheme]
  \label{def:hybridpke}
  \uses{def:spcomp}
  \lean{CatCrypt.Examples.KEMDEM.KEMScheme, CatCrypt.Examples.KEMDEM.DEMScheme, CatCrypt.Examples.KEMDEM.HybridPKE}
  \leanok
  From a KEM and a DEM, the hybrid scheme encapsulates a key, encrypts the payload
  under it with the DEM, and ships both encapsulations.
\end{definition}

n42797.content:
\begin{theorem}[Hybrid correctness]
  \label{thm:hybridpke-correct}
  \uses{def:hybridpke}
  \lean{CatCrypt.Examples.KEMDEM.hybridPKE_correct}
  \leanok
  Component correctness of the KEM and DEM lifts to correctness of the hybrid
  scheme.
\end{theorem}

n42798.content:
\begin{theorem}[Hybrid security bound]
  \label{thm:kemdem-bound}
  \uses{def:hybridpke}
  \lean{CatCrypt.Examples.KEMDEM.pke_security}
  \leanok
  The hybrid scheme's IND-CCA advantage is bounded by the sum of the KEM, DEM, and
  KEM advantages of explicit reductions:
  \[
    \mathsf{Adv}^{\mathrm{CCA}}_{\mathrm{hyb}} \;\le\; \mathsf{Adv}_{\mathrm{KEM}}
    + \mathsf{Adv}_{\mathrm{DEM}} + \mathsf{Adv}_{\mathrm{KEM}}.
  \]
\end{theorem}

n42799.content:
\begin{theorem}[Perfect security of the XOR-DEM hybrid]
  \label{thm:kemdem-perfect}
  \uses{thm:kemdem-bound}
  \lean{CatCrypt.Examples.KEMDEM.pke_perfect_security, CatCrypt.Examples.KEMDEM.xorHybrid_advantage_zero}
  \leanok
  A perfectly-secure KEM composed with the XOR one-time-pad DEM has advantage
  exactly $0$.
\end{theorem}

n42800.content:
\begin{definition}[Commitment scheme]
  \label{def:commscheme}
  \uses{def:spcomp}
  \lean{CatCrypt.Examples.Commitment.CommScheme}
  \leanok
  A commitment scheme has a $\mathsf{commit}$ map (value and randomness to a
  commitment) and a $\mathsf{verify}$ check used at opening.
\end{definition}

n42801.content:
\begin{theorem}[Perfect hiding of the mask commitment]
  \label{thm:comm-hiding}
  \uses{def:commscheme, thm:otp-perfect}
  \lean{CatCrypt.Examples.Commitment.maskComm_perfect_hiding}
  \leanok
  The mask commitment $\mathsf{commit}(r, m) = r \oplus m$ with uniform randomness
  $r$ is perfectly hiding: the hiding advantage is exactly $0$ for every
  adversary, by the one-time-pad argument.
\end{theorem}

n42802.content:
\begin{theorem}[Perfect binding of the identity commitment]
  \label{thm:comm-binding}
  \uses{def:commscheme}
  \lean{CatCrypt.Examples.Commitment.idComm_perfectly_binding}
  \leanok
  The identity commitment cannot be opened to two distinct messages --- it is
  perfectly binding (and, being the complement of the mask commitment, not
  hiding).
\end{theorem}

n42803.content:
\begin{definition}[Additive 2-of-2 sharing]
  \label{def:ss-share}
  \uses{def:spcomp}
  \lean{CatCrypt.Examples.SecretSharing.revealShare}
  \leanok
  The secret $s$ is shared as $(k, k \oplus s)$ for a uniform key $k$; party $0$
  holds $k$ and party $1$ holds $k \oplus s$.
\end{definition}

n42804.content:
\begin{lemma}[Reconstruction]
  \label{lem:ss-reconstruct}
  \uses{def:ss-share}
  \lean{CatCrypt.Examples.SecretSharing.shareXor_reconstruct}
  \leanok
  The two shares reconstruct the secret: $k \oplus (k \oplus s) = s$.
\end{lemma}

n42805.content:
\begin{theorem}[Perfect privacy]
  \label{thm:ss-privacy}
  \uses{def:ss-share}
  \lean{CatCrypt.Examples.SecretSharing.ss_perfect_privacy}
  \leanok
  For either corrupted party, any pair of secrets, and any adversary, the privacy
  advantage from a single share is exactly $0$: one share reveals nothing about
  the secret.
\end{theorem}

n42806.content:
\begin{definition}[Bijection MAC family]
  \label{def:bijmac}
  \uses{def:spcomp}
  \lean{CatCrypt.Examples.MAC.BijMACFamily, CatCrypt.Examples.MAC.BijMACFamily.toMACScheme}
  \leanok
  A bijection MAC family tags each message by a key-indexed bijection
  $\mathrm{Key} \simeq \mathrm{Tag}$, inducing a MAC scheme.
\end{definition}

n42807.content:
\begin{theorem}[Optimal forgery probability]
  \label{thm:bijmac-forgery}
  \uses{def:bijmac}
  \lean{CatCrypt.Examples.MAC.bijMAC_forgery_prob, CatCrypt.Examples.MAC.bijMAC_euf_cma_adv}
  \leanok
  A bijection MAC has single-query EUF-CMA forgery probability exactly
  $1/|\mathrm{Tag}|$: a forged tag verifies under exactly one key, so a blind
  forgery succeeds with probability $1/|\mathrm{Key}| = 1/|\mathrm{Tag}|$.
\end{theorem}

n42808.content:
\begin{corollary}[XOR MAC]
  \label{cor:xormac}
  \uses{thm:bijmac-forgery}
  \lean{CatCrypt.Examples.MAC.boolXorMAC, CatCrypt.Examples.MAC.boolXorMAC_forgery_prob}
  \leanok
  The XOR MAC $\mathsf{mac}(k, m) = k \oplus m$ attains the optimal one-bit forgery
  probability $1/2$.
\end{corollary}

n42809.content:
\begin{definition}[PRF-based encryption]
  \label{def:cpafromprf}
  \uses{def:bijprf}
  \lean{CatCrypt.Examples.CPAFromPRF.BijCPAScheme, CatCrypt.Examples.CPAFromPRF.BijCPAScheme.toBijPRFFamily}
  \leanok
  From a bijection PRF family, the scheme encrypts $m$ as $(r, F(k, r) \oplus m)$
  with fresh uniform $r$; the underlying PRF is exposed for the reduction.
\end{definition}

n42810.content:
\begin{theorem}[Correctness]
  \label{thm:cpafromprf-correct}
  \uses{def:cpafromprf}
  \lean{CatCrypt.Examples.CPAFromPRF.bijCPA_correct}
  \leanok
  Decryption recovers the message: $F(k, r) \oplus (F(k, r) \oplus m) = m$.
\end{theorem}

n42811.content:
\begin{theorem}[Perfect IND-CPA]
  \label{thm:cpafromprf-perfect}
  \uses{def:cpafromprf, thm:bijprf-perfect, thm:otp-perfect}
  \lean{CatCrypt.Examples.CPAFromPRF.bijCPA_perfect_indcpa, CatCrypt.Examples.CPAFromPRF.boolXorCPA_perfect_indcpa}
  \leanok
  Built on a perfect PRF, the scheme has perfect IND-CPA security: advantage
  exactly $0$. Fresh randomness is drawn first and synchronized across the two
  games, and at each $r$ the key coupling makes the ciphertexts coincide.
\end{theorem}

n42812.content:
\begin{theorem}[Computational IND-CPA from a PRF]
  \label{thm:cpafromprf-bound}
  \uses{def:cpafromprf, thm:otp-perfect}
  \lean{CatCrypt.Examples.CPAFromPRF.cpa_from_prf_bound}
  \leanok
  For a general PRF $F$ with advantage $\varepsilon$, replacing $F(k, \cdot)$ by a
  random function turns the scheme into a one-time pad (perfect), so composing the
  PRF-swap hop with the perfect-OTP hop through the advantage triangle inequality
  gives $\mathsf{Adv}^{\mathrm{IND\text{-}CPA}} \le \varepsilon$.
\end{theorem}

n42813.content:
\begin{theorem}[Synthesized reduction]
  \label{thm:cpafromprf-reduction}
  \uses{def:cpafromprf, thm:otp-perfect}
  \lean{CatCrypt.Examples.CPAFromPRF.cpa_from_prf_reduction}
  \leanok
  The PRF-swap hop is discharged, not assumed: an explicit distinguisher
  $R_A(y) = A(r, y \oplus m)$ turns the IND-CPA adversary into a PRF distinguisher,
  and at each fixed randomness the swap advantage \emph{equals}
  $\mathsf{Adv}^{\mathrm{PRF}}(R_A)$. Averaging over the fresh randomness and
  bounding each slice by $\varepsilon$ gives, with no hop hypothesis,
  \[
    \mathsf{Adv}^{\mathrm{IND\text{-}CPA}} \;\le\; 2\varepsilon.
  \]
  The factor two is the two independent PRF replacements, one per challenge world.
\end{theorem}

n42814.content:
\begin{definition}[ElGamal over a prime-order group]
  \label{def:elgamal}
  \uses{def:spcomp}
  \lean{CatCrypt.Examples.ElGamal.elgamalEnc, CatCrypt.Examples.ElGamal.elgamalDDH}
  \leanok
  With public key $\mathit{pk} = g^{x}$, ElGamal encrypts $m$ as $(g^{r}, m \cdot
  \mathit{pk}^{r})$ for fresh $r$. The matching DDH instance fixes
  $\mathsf{ecdh}(g^{a}, g^{b}) = g^{ab}$ on group elements.
\end{definition}

n42816.content:
\begin{theorem}[IND-CPA reduces to DDH]
  \label{thm:elgamal-ddh}
  \uses{def:elgamal}
  \lean{CatCrypt.Examples.ElGamal.elgamal_indcpa_le_ddh}
  \leanok
  ElGamal's IND-CPA advantage is bounded by the DDH advantage of two explicit
  reduction adversaries:
  \[
    \mathsf{Adv}^{\mathrm{IND\text{-}CPA}}_{\mathrm{ElGamal}}(m_0, m_1, A) \;\le\;
    \mathsf{Adv}^{\mathrm{DDH}}(R_{m_0}) + \mathsf{Adv}^{\mathrm{DDH}}(R_{m_1}).
  \]
  The three-hop argument passes through the game where the mask is uniform, in
  which the message is absorbed and the two challenges coincide.
\end{theorem}

n42817.content:
\begin{theorem}[Exact real-or-random bound]
  \label{thm:elgamal-eq-ddh}
  \uses{def:elgamal}
  \lean{CatCrypt.Examples.ElGamal.elgamal_indcpa_eq_ddh}
  \leanok
  In the real-or-random framing (real encryption versus a random ciphertext), the
  advantage \emph{equals} a single DDH advantage --- no factor and no sum:
  \[
    \mathsf{Adv}(\mathrm{Enc}\,m_0,\ \mathrm{random}) \;=\;
    \mathsf{Adv}^{\mathrm{DDH}}(R_{m_0}).
  \]
  This matches SSProve-Rocq's exact one-time-secrecy result; the two-message
  left-or-right advantage above is a different, two-term quantity.
\end{theorem}

n42818.content:
\begin{definition}[IND-CCA game]
  \label{def:indcca}
  \uses{def:spcomp}
  \lean{CatCrypt.Crypto.SecurityDefs.INDCCA_Game, CatCrypt.Crypto.SecurityDefs.ccaDecOracle}
  \leanok
  The adversary receives the challenge ciphertext and a decryption oracle that
  answers every ciphertext except the challenge; the ideal variant answers with
  the always-reject oracle.
\end{definition}

n42819.content:
\begin{theorem}[Generic CCA reduction]
  \label{thm:indcca-reduction}
  \uses{def:indcca}
  \lean{CatCrypt.Crypto.SecurityDefs.INDCCA_reduces_to_INDCPA}
  \leanok
  For any scheme, the IND-CCA advantage is bounded by its IND-CPA advantage
  (against the reject-oracle adversary) plus the two integrity gaps measuring how
  far the real decryption oracle is from always rejecting.
\end{theorem}

n42820.content:
\begin{theorem}[Encrypt-then-MAC is authenticated encryption]
  \label{thm:etm-cca}
  \uses{thm:indcca-reduction, thm:etm-perfect}
  \lean{CatCrypt.Examples.EtMCCA.boolEtM_indcca_reduces}
  \leanok
  For the one-time-pad Encrypt-then-MAC scheme the confidentiality term is exactly
  $0$ (its perfect IND-CPA security), so its entire IND-CCA advantage is the pair
  of MAC-integrity gaps: chosen-ciphertext security is precisely the
  unforgeability of the MAC.
\end{theorem}

n42821.content:
\begin{definition}[Single-block CTR]
  \label{def:ctr}
  \uses{def:cpafromprf}
  \lean{CatCrypt.Examples.CTRMode.CTRBlockScheme, CatCrypt.Examples.CTRMode.CTRBlockScheme.toBijCPAScheme}
  \leanok
  A CTR block scheme is a keystream bijection family $\mathrm{Block} \to
  (\mathrm{Key} \simeq \mathrm{Block})$ modelling $k \mapsto E(k, \mathit{ctr})$;
  it maps directly onto the PRF-based encryption scheme.
\end{definition}

n42822.content:
\begin{theorem}[Perfect IND-CPA]
  \label{thm:ctr-perfect}
  \uses{def:ctr, thm:cpafromprf-perfect}
  \lean{CatCrypt.Examples.CTRMode.ctr_perfect_indcpa, CatCrypt.Examples.CTRMode.boolCTR_perfect_indcpa}
  \leanok
  Single-block CTR from a bijection block cipher has perfect IND-CPA security:
  advantage exactly $0$, inherited from the CPA-from-PRF result. (Multi-block CTR
  needs a product-of-bijections argument and is out of scope.)
\end{theorem}

n42823.content:
\begin{theorem}[Computational bound from a PRF]
  \label{thm:ctr-bound}
  \uses{def:ctr, thm:cpafromprf-bound}
  \lean{CatCrypt.Examples.CTRMode.ctr_indcpa_bound}
  \leanok
  For a general block cipher with PRF-advantage $\varepsilon$, single-block CTR has
  $\mathsf{Adv}^{\mathrm{IND\text{-}CPA}} \le \varepsilon$, routing through the same
  PRF-swap and perfect hops as CPA-from-PRF.
\end{theorem}

n42824.content:
\begin{definition}[Key-agreement distinguishing game]
  \label{def:ka-game}
  \uses{def:spcomp, def:elgamal}
  \lean{CatCrypt.Examples.DiffieHellman.KA_Game_Real, CatCrypt.Examples.DiffieHellman.KA_Advantage}
  \leanok
  The real game hands the distinguisher the transcript $(g^{a}, g^{b})$ and the
  true shared key $g^{ab}$; the ideal game replaces the key by a uniform group
  element. The advantage is the distance between them.
\end{definition}

n42825.content:
\begin{theorem}[Key indistinguishability equals DDH]
  \label{thm:ka-ddh}
  \uses{def:ka-game}
  \lean{CatCrypt.Examples.DiffieHellman.ka_advantage_eq_ddh}
  \leanok
  The key-agreement advantage is \emph{equal} to the DDH advantage of an explicit
  reduction adversary that repackages a DDH triple $(g^{a}, g^{b}, z)$ into the
  transcript-plus-candidate-key shape:
  \[
    \mathsf{Adv}^{\mathrm{KA}}(D) \;=\; \mathsf{Adv}^{\mathrm{DDH}}(R_D).
  \]
\end{theorem}

n42826.content:
\begin{corollary}[Security under DDH]
  \label{cor:ka-secure}
  \uses{thm:ka-ddh}
  \lean{CatCrypt.Examples.DiffieHellman.ka_secure_under_ddh}
  \leanok
  If DDH is $\varepsilon$-hard in the group, Diffie--Hellman key agreement has
  advantage at most $\varepsilon$.
\end{corollary}

n42827.content:
\begin{definition}[Single-block CBC]
  \label{def:cbc}
  \uses{def:cpafromprf}
  \lean{CatCrypt.Examples.CBCMode.CBCBlockCipher}
  \leanok
  A CBC block cipher carries two coherent views --- a permutation per key (for
  decryption) and a bijection $k \mapsto F(k, x)$ per input (for a uniform output)
  --- tied by a coherence law. Encryption is $(\mathit{IV}, F(k, \mathit{IV}
  \oplus m))$.
\end{definition}

n42828.content:
\begin{theorem}[Perfect IND-CPA]
  \label{thm:cbc-perfect}
  \uses{def:cbc, thm:cpafromprf-perfect}
  \lean{CatCrypt.Examples.CBCMode.cbc_perfect_indcpa, CatCrypt.Examples.CBCMode.boolCBC_perfect_indcpa}
  \leanok
  Single-block CBC from a two-sided bijection block cipher has perfect IND-CPA
  security: advantage exactly $0$, via the per-IV random-key coupling. (Multi-block
  chaining is only computationally secure --- a PRP reduction --- and is out of
  scope.)
\end{theorem}

n42829.content:
\begin{theorem}[Computational bound from a PRP]
  \label{thm:cbc-bound}
  \uses{def:cbc, thm:cpafromprf-bound}
  \lean{CatCrypt.Examples.CBCMode.cbc_indcpa_bound}
  \leanok
  For a general block cipher with PRP-advantage $\varepsilon$, single-block CBC has
  $\mathsf{Adv}^{\mathrm{IND\text{-}CPA}} \le 2\varepsilon$ --- the real-or-random
  ladder swaps the permutation for random on both the real-true and real-false
  sides, with the uniform-IV masking perfect in between.
\end{theorem}

n42830.content:
\begin{definition}[Polynomial share]
  \label{def:shamir-share}
  \uses{def:spcomp}
  \lean{CatCrypt.Examples.ShamirSecretSharing.shareVal}
  \leanok
  A degree-${<}t$ polynomial is its constant term $s$ plus $t-1$ free
  coefficients; the share at $q$ is $f(q) = s + \sum_i a_i q^{i+1}$.
\end{definition}

n42831.content:
\begin{theorem}[Reconstruction]
  \label{thm:shamir-reconstruct}
  \uses{def:shamir-share}
  \lean{CatCrypt.Examples.ShamirSecretSharing.shamir_reconstruct}
  \leanok
  Lagrange interpolation through any $t$ distinct evaluation points recovers
  $f(0) = s$.
\end{theorem}

n42832.content:
\begin{theorem}[Perfect privacy]
  \label{thm:shamir-privacy}
  \uses{def:shamir-share}
  \lean{CatCrypt.Examples.ShamirSecretSharing.shamir_perfect_privacy}
  \leanok
  For any $t-1$ nonzero evaluation points, any two secrets, and any adversary, the
  distinguishing advantage from those $t-1$ shares is exactly $0$. The two games
  couple by translating the free coefficients by those of $(s_1 - s_0)\,L$, where
  $L$ is the degree-${<}t$ polynomial that is $1$ at $0$ and $0$ at every revealed
  point --- a bijection of the coefficient space, so no Vandermonde inversion is
  needed.
\end{theorem}

n42833.content:
\begin{theorem}[Completeness]
  \label{thm:sigma-complete}
  \uses{def:spcomp}
  \lean{CatCrypt.Examples.SigmaProtocol.simpleSigma_complete}
  \leanok
  Honest execution with a valid witness always verifies.
\end{theorem}

n42834.content:
\begin{theorem}[Special honest-verifier zero knowledge]
  \label{thm:sigma-shvzk}
  \uses{thm:sigma-complete}
  \lean{CatCrypt.Examples.SigmaProtocol.simpleSigma_shvzk, CatCrypt.Examples.SigmaProtocol.simpleSigma_shvzk_zero_adv}
  \leanok
  Real and simulated transcripts are identically distributed: the simulator, given
  the challenge, produces a transcript coupled to the real one through a single
  bijection, so the distinguishing advantage is $0$.
\end{theorem}

n42835.content:
\begin{theorem}[Special soundness]
  \label{thm:sigma-sound}
  \uses{thm:sigma-complete}
  \lean{CatCrypt.Examples.SigmaProtocol.simpleSigma_special_sound}
  \leanok
  Two accepting transcripts sharing a commitment but differing in challenge yield
  the witness through an explicit extractor.
\end{theorem}

n42836.content:
\begin{theorem}[Commitment hiding and binding]
  \label{thm:sigma-commitment}
  \uses{thm:sigma-shvzk, thm:sigma-sound}
  \lean{CatCrypt.Examples.SigmaProtocol.simpleSigma_hiding, CatCrypt.Examples.SigmaProtocol.simpleSigma_binding}
  \leanok
  The associated commitment is perfectly hiding (a direct instance of SHVZK's
  one-time-pad coupling) and binding (a double opening yields two accepting
  transcripts, hence the witness by special soundness).
\end{theorem}

n42962.type_full:
∀ (p₁ p₂ : CatCrypt.Deep.DeepPackage),
  Eq (CatCrypt.Crypto.runPkg (p₁.link p₂))
    (have this := Classical.dec (Membership.mem p₁.exports.ops (Prod.mk 0 (Prod.mk Unit Bool)));
    dite (Membership.mem p₁.exports.ops (Prod.mk 0 (Prod.mk Unit Bool)))
      (fun h =>
        have vc := p₁.impl 0 Unit Bool h Unit.unit;
        have env := fun op' dom' codom' x' =>
          have this := Classical.dec (Membership.mem p₂.exports.ops (Prod.mk op' (Prod.mk dom' codom')));
          dite (Membership.mem p₂.exports.ops (Prod.mk op' (Prod.mk dom' codom')))
            (fun h₂ => (p₂.impl op' dom' codom' h₂ x').code) fun h₂ => CatCrypt.Deep.RawCode.fail;
        CatCrypt.Deep.RawCode.evalWith (fun op dom codom x => (env op dom codom x).eval) vc.code)
      fun h => CatCrypt.Core.SPComp.pure true)

