∀ {α : Type u_1} {β : Type u_2} {γ : Type u_3} {δ : Type u_4} {d₁ : CatCrypt.Prob.SDistr α}
  {d₂ : CatCrypt.Prob.SDistr β} {f₁ : α → CatCrypt.Prob.SDistr γ} {f₂ : β → CatCrypt.Prob.SDistr δ} {R : α → β → Prop}
  {S : γ → δ → Prop},
  CatCrypt.Prob.liftR R d₁ d₂ →
    (∀ (a : α) (b : β), R a b → CatCrypt.Prob.liftR S (f₁ a) (f₂ b)) → CatCrypt.Prob.liftR S (d₁.bind f₁) (d₂.bind f₂)

