  {Ψ : CatCrypt.Relational.RPost α β} {Θ : CatCrypt.Relational.RPost γ δ} {c₁ : CatCrypt.Core.SPComp α}
  {c₂ : CatCrypt.Core.SPComp β} {f₁ : α → CatCrypt.Core.SPComp γ} {f₂ : β → CatCrypt.Core.SPComp δ},
